    /// Extra chips added in the 2.0 Library rebuild (grouped by category, appended after newChips).
    /// Extra chips added in the 2.0 Library rebuild (grouped by category, appended after newChips).
    /// Extra chips added in the 2.0 Library rebuild (grouped by category, appended after newChips).
    static func rebuildChips(for category: PromptPresetCategory) -> [PromptPreset] {
        switch category {
        case .pose:
            return [
                .init(id: "pose.candidtravel", label: "Caught Off-Guard", phrase: "an unposed candid instant, the subject unaware of the camera and mid-gesture", badge: .green),
            ]
        case .expression: return []
        case .placement:
            return [
                .init(id: "obj.condensation", label: "iced & beaded", phrase: "a chilled glass beaded with fresh condensation, large crystal-clear ice cubes and a frosty cold look, filled near the brim with a fresh garnish", badge: .green),
                .init(id: "obj.steam", label: "rising steam", phrase: "wisps of hot steam rising and catching the light against the darker background, a glossy fresh-cooked surface reading hot off the stove", badge: .green),
                .init(id: "obj.finedining", label: "tweezered plating", phrase: "fine-dining Michelin-style plating, precisely placed components with delicate micro-herbs and an elegant sauce swoosh, refined editorial restraint", badge: .green),
                .init(id: "obj.rusticstyle", label: "rustic styling", phrase: "rustic farmhouse styling with a weathered knife-marked board, a crumpled natural linen napkin, matte stoneware and vintage patinated cutlery layered for depth", badge: .green),
                .init(id: "obj.glosspull", label: "glossy pull", phrase: "a glistening dewy close detail — a molten cheese pull, glossy glaze or syrup drip — caught at its most appetizing peak", badge: .green),
                .init(id: "obj.freshgarnish", label: "fresh garnish", phrase: "styled with fresh vivid garnishes, dewy herbs and scattered ingredient cues suggesting just-picked freshness", badge: .green),
            ]
        case .framing:
            return [
                .init(id: "frame.frameinframe", label: "frame-in-frame", phrase: "framed within a frame through angular geometric architecture, layered depth leading the eye to the small distant subject", badge: .green),
            ]
        case .layout: return []
        case .angle:
            return [
                .init(id: "angle.oblique45", label: "45° oblique aerial", phrase: "low-altitude oblique aerial view at a 45-degree drone angle, a sweeping sense of scale", badge: .green),
                .init(id: "angle.plate45", label: "45° plate hero", phrase: "shot at a 45-degree angle looking down at the plate from dinner-table eye level, revealing the height and layered garnish of the dish, background softly blurred", badge: .green),
            ]
        case .lens:
            return [
                .init(id: "lens.35mm", label: "35mm f/1.4", phrase: "shot on a 35mm f/1.4 lens, natural environmental perspective and a gently softened background", badge: .green),
                .init(id: "lens.35mmcandid", label: "35mm candid", phrase: "shot on a 35mm lens at close proximity, immersive documentary framing with the environment wrapping around the subject", badge: .green),
                .init(id: "lens.stacked", label: "focus-stacked deep macro", phrase: "extreme focus-stacked macro, razor-sharp front to back, every facet and engraving crisp across the whole piece", badge: .green),
                .init(id: "lens.phonesnap", label: "Phone Snapshot", phrase: "the loose imperfect framing of a quick phone snapshot, slightly tilted and grabbed in a hurry", badge: .green),
                .init(id: "lens.lightstreaks", label: "Long-exposure trails", phrase: "a long-exposure capture, moving lights drawn into smooth continuous glowing trails while the structure stays sharp", badge: .green),
            ]
        case .environment:
            return [
                .init(id: "env.darkseamless", label: "dark seamless", phrase: "against a deep near-black seamless studio backdrop, the subject glowing out of the shadow", badge: .green),
                .init(id: "env.amberhaze", label: "amber haze", phrase: "outdoors bathed in warm amber haze, low sun flaring through drifting atmosphere", badge: .green),
                .init(id: "env.wetfloor", label: "wet reflective floor", phrase: "on a wet glossy reflective floor in a dark cinematic set, the paint and lights mirrored below", badge: .green),
                .init(id: "env.cleanroom", label: "cleanroom", phrase: "inside a sterile semiconductor cleanroom with reflective white surfaces and rows of wafer-processing equipment", badge: .green),
                .init(id: "env.perspective", label: "atmospheric depth", phrase: "deep atmospheric perspective, a warm saturated detailed foreground fading through stacked value planes into a cool desaturated misty background", badge: .green),
                .init(id: "env.sanddunes", label: "sand dunes", phrase: "across sweeping sand dunes with sinuous S-curve ridgelines and rippled wind-carved texture", badge: .green),
                .init(id: "env.silkyseascape", label: "silky seascape", phrase: "on a rocky shore where a long exposure smooths the sea into soft flowing mist swirling around dark wet foreground rocks", badge: .green),
                .init(id: "env.ancientplaza", label: "ancient plaza", phrase: "in a historic stone plaza surrounded by old-world architecture, worn cobblestones underfoot", badge: .green),
                .init(id: "env.stonearch", label: "stone archway", phrase: "viewed through a dark ornate stone archway in the foreground framing the distant scene", badge: .green),
                .init(id: "env.coastaltown", label: "coastal town", phrase: "over a dense coastal town of terracotta rooftops meeting the sea", badge: .green),
                .init(id: "env.templeskyline", label: "temple skyline", phrase: "the tiered rooftops and spires of an ancient temple complex against the open sky", badge: .green),
                .init(id: "env.market", label: "open-air market", phrase: "in a colorful open-air market with stalls of textiles, spices and produce", badge: .green),
                .init(id: "env.terracedhills", label: "terraced hills", phrase: "across steep terraced hillsides of sculpted farming steps receding into the distance", badge: .green),
                .init(id: "env.blackvelvet", label: "black velvet", phrase: "resting on deep black velvet that swallows all light, a pure black field around the subject", badge: .green),
                .init(id: "env.wetslate", label: "wet dark slate", phrase: "on a dark wet slate surface with a clean mirror reflection pooling beneath the subject", badge: .green),
                .init(id: "env.darkmarble", label: "dark polished marble", phrase: "on dark polished marble with a soft mirror reflection under the subject and subtle veined stone texture", badge: .green),
                .init(id: "env.afterrain", label: "Just After Rain", phrase: "the scene glossy and dark from rain that just stopped, puddles holding the sky", badge: .green),
            ]
        case .lighting:
            return [
                .init(id: "light.venetianbars", label: "venetian bars", phrase: "stark venetian-blind shadow bars raking hard across the face and wall, a cage-like slatted shadow pattern from a single hard light through the blinds", badge: .green),
                .init(id: "light.horrordread", label: "underlight dread", phrase: "eerie underlighting from a single source below the eyeline, shadows cast upward distorting the face, hollow shadowed eye sockets and a sickly uncanny glow", badge: .green),
                .init(id: "light.br2049fog", label: "cyan fog", phrase: "cold hazy cyan-blue fog filling the frame, a single giant motivated glow spreading through the mist like watercolor, with a small pocket of toxic radioactive-orange", badge: .green),
                .init(id: "light.ecomtwolight", label: "e-com two-light", phrase: "soft even two-light studio setup, a key softbox at 45 degrees with a white fill card opposite, minimal soft contact shadow beneath", badge: .green),
                .init(id: "light.stripboxrake", label: "stripbox rake", phrase: "a single graduated stripbox raking across the glossy surface, the specular highlight fading smoothly from bright to dark, negative fill deepening the shadow side", badge: .green),
                .init(id: "light.darkfield", label: "dark-field glow", phrase: "dark-field lighting, a bright rim light defining the glowing edges against a black surround, luminous contour lines tracing the clear form with black flags for negative fill", badge: .green),
                .init(id: "light.brightfield", label: "bright-field tent", phrase: "bright-field tent lighting, the product cocooned in soft diffused white light from all sides, smooth bright gradient reflections wrapping the surface, clean shadowless illumination with no camera reflection", badge: .green),
                .init(id: "light.backlitliquid", label: "backlit liquid", phrase: "backlit through the liquid, the light source directly behind making the translucent contents glow, bright outer edge lines tracing the curves", badge: .green),
                .init(id: "light.splashfreeze", label: "splash freeze", phrase: "high-speed strobe splash lighting, frozen crystalline droplets suspended mid-air, strip softboxes with a gridded accent kicker, an energetic frozen liquid crown", badge: .green),
                .init(id: "light.matchedshadow", label: "matched drop shadow", phrase: "a soft matched drop shadow on the surface below, aligned with the key light to ground the floating object", badge: .green),
                .init(id: "light.raking", label: "raking light", phrase: "directional raking light skimming across the surface at a low 45-degree angle, throwing every grain and weave of texture into tactile relief", badge: .green),
                .init(id: "light.flateven", label: "flat even light", phrase: "flat even frontal lighting, soft and shadowless, every surface lit uniformly with no drama", badge: .green),
                .init(id: "light.perfumedrama", label: "perfume drama", phrase: "a single hard low-key light carving the subject out of darkness, one bright specular edge and a deep enveloping shadow, dramatic perfume-campaign mood", badge: .green),
                .init(id: "light.silkgradient", label: "silk gradient", phrase: "lit by a large overhead silk casting one long unbroken soft gradient reflection sweeping down the glossy paint, no hotspots, smooth falloff along the body line", badge: .green),
                .init(id: "light.subtractive", label: "black-flag subtractive", phrase: "subtractive studio lighting with large black flags carving deep dark reflection shapes into the glossy flanks, metal-flake sparkle glinting in the highlights", badge: .green),
                .init(id: "light.paintstripe", label: "light-paint stripe", phrase: "long-exposure light-painting on a pure black background, a single luminous highlight stripe reflected along the body line under the windows, dramatic controlled gradient on the paint", badge: .green),
                .init(id: "light.dustplume", label: "backlit dust", phrase: "a huge dust plume backlit by a low golden sun so the drifting dust glows, warm rim light along the edges", badge: .green),
                .init(id: "light.rgbtubes", label: "RGB rim tubes", phrase: "a hard directional key raking across the body with colored RGB tube rim lights separating the subject from a black background and a soft overhead modeling light", badge: .green),
                .init(id: "light.amberlitho", label: "amber lithography", phrase: "bathed in monochromatic amber-yellow photolithography light, a sterile glowing yellow ambience on reflective surfaces", badge: .green),
                .init(id: "light.gelaccent", label: "cyan/magenta gel", phrase: "saturated cyan and magenta gelled accent light raking the machinery from the sides, a cool high-tech glow blended with a warm natural key", badge: .green),
                .init(id: "light.refeven", label: "even reference light", phrase: "flat even reference lighting, no drama, every surface and angle clearly readable", badge: .green),
                .init(id: "light.godrays", label: "god rays", phrase: "volumetric god rays streaming through atmospheric haze, soft shafts of light raking across the scene", badge: .green),
                .init(id: "light.sunstar", label: "sunstar", phrase: "a crisp sunstar bursting over the ridge, narrow-aperture sunburst with sharp diffraction spikes and minimal flare", badge: .green),
                .init(id: "light.alpenglow", label: "alpenglow", phrase: "warm rosy-orange alpenglow burning on the upper peaks while the valleys sit in cool blue shadow", badge: .green),
                .init(id: "light.wildliferim", label: "wildlife rim", phrase: "warm golden rim light glowing along the fur edge at sunrise, backlit with a bright catchlight sparking in the eye", badge: .green),
                .init(id: "light.trails", label: "light trails", phrase: "long-exposure night light trails, glowing red and white streaks of traffic drawn through the streets", badge: .green),
                .init(id: "light.mccurry", label: "McCurry portrait light", phrase: "warm high-contrast directional light on the face, bright catchlights in the eyes and deep shaping shadows", badge: .green),
                .init(id: "light.celkeyrim", label: "cel key + colored rim", phrase: "a strong top-left key light casting a hard-edged cel shadow, with a thin cool-blue rim light tracing the hair and shoulders to separate the figure from a dark background", badge: .green),
                .init(id: "light.impactlines", label: "shonen impact lines", phrase: "explosive radial speed lines and dynamic impact bursts driving the eye to the action, high-contrast dramatic panel energy", badge: .green),
                .init(id: "light.beverageback", label: "backlit glow", phrase: "lit from directly behind so the translucent liquid glows, backlit glassware catching the light and separated against a darker background", badge: .green),
                .init(id: "light.sparkleduo", label: "soft base + sparkle spot", phrase: "a soft diffused softbox base for smooth metal gradients plus a single small hard spotlight raking across the facets, igniting sharp pinfire sparkles and prismatic fire", badge: .green),
                .init(id: "light.firebeam", label: "fiber-optic fire beam", phrase: "a thin intense fiber-optic beam striking the gem face near the lens axis, prismatic red-blue-green fire flashing back from the facets, crisp specular pinfire scintillation", badge: .green),
                .init(id: "light.dialspot", label: "dial projection spot", phrase: "soft diffused light on the polished case with a precise narrow projected spotlight snapping the dial texture crisp and saturated", badge: .green),
                .init(id: "light.stripedge", label: "strip-box edge line", phrase: "a single tall continuous vertical strip highlight running the full length of the glass, one elegant unbroken specular edge line down the form", badge: .green),
                .init(id: "light.backlitglass", label: "backlit glass caustics", phrase: "lit from a bright glowing background behind the clear glass, light refracting through it and casting luminous caustic patterns, glowing halo edges tracing the silhouette", badge: .green),
                .init(id: "light.octagloss", label: "octabox gloss catchlight", phrase: "a large octabox overhead throwing one big round specular catchlight across the glossy surface, wet reflective sheen and a clean rounded highlight", badge: .green),
                .init(id: "light.grazetexture", label: "grazing texture light", phrase: "diffused light raking in at a low grazing angle across the surface, catching every peak and ridge with fine micro-shadows and tactile relief", badge: .green),
                .init(id: "light.snootsmoke", label: "snooted side light", phrase: "a single snooted side light at ninety degrees lighting only the wisps and curls, the background left unlit to pure black, sharp flash-frozen edges", badge: .green),
                .init(id: "light.backlitfreeze", label: "backlit high-speed freeze", phrase: "backlit against pure black and frozen with an ultra-short flash, billowing organic filaments caught tack-sharp in mid-motion", badge: .green),
                // "light.smokeside" removed: it duplicated light.snootsmoke's label ("snooted side
                // light") with a near-identical phrase — two indistinguishable chips in the picker.
                // No recipe or conflict-pair referenced it (grep-verified before removal).
                .init(id: "light.harmattan", label: "Dusty Haze Sun", phrase: "sun filtered through dusty atmospheric haze, its disc dimmed to a soft glowing coin", badge: .green),
            ]
        case .style:
            return [
