                .init(id: "style.painterlyconcept", label: "painterly concept", phrase: "painterly digital concept art, confident brushwork, strong value structure and sharp readable edges", badge: .green),
                .init(id: "style.silhouettefirst", label: "silhouette-first", phrase: "designed silhouette-first, a strong distinctive outline recognizable in shadow, clean big-to-small shape hierarchy and controlled detail density", badge: .green),
