                .init(id: "style.celshade", label: "cel-shaded hard-block", phrase: "cel-shaded anime with bold clean outlines, a single hard-edged two-tone shadow and decisive color blocking, no gradients", badge: .green),
                .init(id: "style.oga", label: "Kazuo Oga gouache scenery", phrase: "a hand-painted Kazuo Oga background, wet-on-wet gouache washes, soft-edged atmospheric clouds and layered transparent-over-opaque paint", badge: .green),
                .init(id: "style.mangapen", label: "G-pen manga inking", phrase: "black-and-white manga ink with tapered G-pen line-weight variation, kakeami cross-hatching nets and solid black beta fills, no color", badge: .green),
                .init(id: "style.shoujoemotion", label: "shoujo sparkle + florals", phrase: "a shoujo manga treatment with large sparkly eyes and star-shaped catchlights, elongated delicate features and an abstract floral emotion background", badge: .green),
                .init(id: "style.chunkhair", label: "90s chunk-highlight cel", phrase: "a 1990s cel-anime finish with flat hand-painted color, hard-edge cel shadows and blocky chunk highlights on the hair", badge: .green),
                .init(id: "style.seinen", label: "seinen ink-wash realism", phrase: "a seinen manga treatment, anatomically accurate rendering with ink-wash atmosphere, minimal screentone and stark solid-black shadow areas", badge: .green),
                .init(id: "style.kennalong", label: "kenna long-exposure", phrase: "minimalist fine-art long exposure in the Michael Kenna tradition, silky smoothed water and blurred clouds, dawn mist and meditative wabi-sabi stillness", badge: .green),
