            ]
        case .color:
            return [
                .init(id: "color.furyamber", label: "fury road amber", phrase: "hypersaturated Mad Max desert grade, pure saturated orange sand and sky with deep saturated teal-blue in the shadows, bold graphic blockbuster color", badge: .green),
                .init(id: "color.neutralaccurate", label: "color-accurate", phrase: "clean neutral daylight-balanced color, accurate white balance, true-to-life color rendering", badge: .green),
                .init(id: "color.splittone", label: "split-tone brand", phrase: "split-toned signature grade, cool teal shadows against warm cream highlights, a cohesive ownable campaign palette", badge: .green),
                .init(id: "color.velvia", label: "Velvia slide", phrase: "shot on Fuji Velvia slide film, vivid saturated blues and greens with deep punchy contrast, the classic grand-vista look", badge: .green),
