                .init(id: "color.ghibli", label: "Ghibli luminous palette", phrase: "a luminous but restrained Ghibli palette of viridian and bamboo greens against a warm chrome-yellow sky, cerulean blues and burnt-sienna earth shadows", badge: .green),
                .init(id: "color.crtwarm", label: "CRT-warm faded 90s", phrase: "a CRT-warm faded-photograph palette of muted reds, smoky teal and faded mustard, low saturation with subtle 35mm film noise", badge: .green),
                .init(id: "color.ovaneon80s", label: "80s OVA neon", phrase: "an oversaturated 80s OVA palette of electric blue and hot pink with harsh dramatic backlighting, neon glow and faint chromatic aberration", badge: .green),
                .init(id: "color.amberblack", label: "amber & black Old-Master", phrase: "a warm amber-and-black low-key grade, cognac and gold tones against deep painterly Dutch-Golden-Age shadow", badge: .green),
                .init(id: "color.steelcool", label: "cool steel & silver", phrase: "a cool grey, steel-blue and silver palette, clean neutral highlights for platinum and chrome", badge: .green),
                .init(id: "color.neutralgem", label: "neutral daylight gem-true", phrase: "neutral daylight color balance rendering true gem color and full diamond brilliance, clean and accurate", badge: .green),
                .init(id: "color.singlehue", label: "single saturated hue", phrase: "a single saturated hue washed over the subject against black, one bold gel-color glowing out of the darkness", badge: .green),
                .init(id: "color.trix", label: "tri-x 400", phrase: "shot on Kodak Tri-X 400, prominent sharp grain, high contrast and dimensional blacks, gritty pushed monochrome", badge: .green),
                .init(id: "color.hp5", label: "ilford hp5", phrase: "shot on Ilford HP5 Plus 400, gritty grain, strong shadows and atmospheric contrast, detail fading into the blacks", badge: .green),
                .init(id: "color.tmax", label: "t-max fine grain", phrase: "shot on Kodak T-Max, clean fine tabular grain, a wide smooth tonal range and rich shadow detail, fine-art print quality", badge: .green),
                .init(id: "color.zonesystem", label: "zone system", phrase: "full Zone System monochrome, every tone placed from pure black to brilliant white, a complete dramatic tonal scale", badge: .green),
                .init(id: "color.selenium", label: "selenium split", phrase: "selenium-toned split monochrome, cool near-black shadows with a faint warm highlight bite, deep silver-gelatin blacks", badge: .green),
                .init(id: "color.fadedpostcard", label: "Faded Postcard", phrase: "the warm sun-bleached color of an old postcard left in a shop window, gently faded and slightly pink", badge: .green),
            ]
        }
    }

