    static let recipes: [SceneRecipe] = [
        .init(id: "rcp.interiors.kitchen-marble-waterfall", studio: "interiors", title: "Kitchen, marble waterfall", subjectExample: "Modern luxury kitchen interior with a large marble-waterfall island at the center, dark grey matte cabinet drawers, an integrated wine fridge and glass-front beverage cooler built into the island. Wood-grain tall cabinets on one wall housing a stack of built-in black ovens and a coffee machine, a beige minimalist cabinet wall behind with a marble slab backsplash and hidden LED strip lighting underneath. Black pendant lights and a track light hanging from the ceiling, a small potted plant and wooden bowls on the countertop, floor-to-ceiling black-framed sliding glass doors opening onto a garden with trimmed hedges and trees. Light grey large-format floor tiles, bright natural daylight coming through the glass wall mixed with warm interior lighting. Wide-angle interior shot, eye-level perspective, architectural photography, sharp focus throughout.", chipIDs: [], note: "A marble-waterfall island with a built-in wine fridge, garden through the glass wall.", badge: .green, featured: false, tier: .klein9B, steps: 20, quality: .best, aspectW: 1, aspectH: 1, seed: 3419085752527533979),
        .init(id: "rcp.cinema.typhoon-helm", studio: "cinema", title: "Helm in the Typhoon", subjectExample: "A lone fisherman standing at the helm of a small wooden boat, gripping the wheel with both hands, body braced against the wind, soaked clothes clinging to him, expression of fierce determination.\nMassive waves crashing over the bow, boat tilted at a steep angle riding up a towering wave, spray and foam exploding into the air, rain lashing sideways.\nOpen ocean during a colossal typhoon, a giant swirling storm system visible on the horizon, dark churning clouds spiraling upward, distant lightning strikes illuminating the storm wall.\nDramatic low-key lighting, greenish-grey stormy atmosphere, lightning flash casting harsh rim light on the boat and figure, deep shadows, high contrast.\nPhotorealistic, cinematic wide shot, shot on 35mm lens, ultra-detailed water simulation, dynamic composition, 8k resolution, hyperrealistic.", chipIDs: [], note: "A fisherman braced at the wheel as a wall of wave rears over the bow.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 8750992039986167224),
        .init(id: "rcp.cinema.heist-crash-getaway", studio: "cinema", title: "The Getaway Crash", subjectExample: "A black pickup truck crashed head-on into a large tree, the front end completely crumpled and mangled, hood bent upward, windshield shattered, smoke rising from the engine.\nRear doors and side doors of the truck hanging wide open, sports duffel bags scattered on the ground behind the vehicle, some bags burst open with cash spilling out, loose banknotes scattered across the asphalt and blowing in the wind.Two criminals sprinting away from the crash scene into the distance, police cars with flashing lights approaching in the background, police officers running after them with weapons drawn.Night scene lit by red and blue police light flashes, harsh headlight beams cutting through smoke and dust, dramatic shadows, streetlight glow on the wet asphalt reflecting the lights.Photorealistic, cinematic action movie still, wide-angle dynamic composition, motion blur on running figures, ultra-detailed, 8k resolution, hyperrealistic.", chipIDs: [], note: "A getaway truck wrapped around a tree, cash spilling as the sirens close in.", badge: .green, featured: false, tier: .klein9B, steps: 10, quality: .best, aspectW: 1, aspectH: 1, seed: 10937788284144021032),
        .init(id: "rcp.cities.aerial-kilometer-up", studio: "cities", title: "City From a Kilometer Up", subjectExample: "Top-down aerial view of a sprawling city from 1 kilometer altitude, straight down perspective, grid of streets and buildings visible below, tiny cars and pedestrians as small dots. Rooftops, parks, and rivers scattered across the urban layout. Bright daylight, soft shadows cast by buildings. Photorealistic, drone photography style, ultra-detailed, sharp focus, hyperrealistic.", chipIDs: [], note: "The city straight down from a kilometre up, streets as a fine grid.", badge: .green, featured: false, tier: .klein9B, steps: 8, quality: .best, aspectW: 1, aspectH: 1, seed: 6388003191515728042),
        .init(id: "rcp.automotive.f1-cockpit-pov", studio: "automotive", title: "F1 Cockpit POV", subjectExample: "Onboard cockpit view from inside a Formula 1 race car, driver's gloved hands gripping the steering wheel with multiple buttons and displays, halo bar visible at the top of the frame, front wing and tires visible at the bottom edge of the shot.Racetrack stretching ahead with a sweeping curve, several rival race cars visible ahead on the track jostling for position, motion blur on the barriers and grandstands whipping past at high speed.Blurred crowd in the grandstands, trackside advertising boards as streaks of color, tire marks on the tarmac, distant pit buildings, spray of dust or dry rubber smoke off the tires ahead.Bright daylight, harsh sunlight glinting off the car's bodywork and helmet visor reflection, high contrast, vivid saturated colors, lens flare from the sun.Photorealistic, cinematic first-person POV shot, wide-angle lens distortion, ultra-detailed, sharp foreground with motion-blurred background, 8k resolution, hyperrealistic, high-speed action photography.", chipIDs: [], note: "Onboard from the halo, hands on the wheel, rivals jostling into the corner.", badge: .green, featured: false, tier: .klein9B, steps: 8, quality: .standard, aspectW: 1, aspectH: 1, seed: 3432432432432535),
        .init(id: "rcp.interiors.hallway-sunburst-mirror", studio: "interiors", title: "Entrance Hall, Sunburst Mirror", subjectExample: "An elegant entrance hallway, a large round sunburst mirror made of layered gold metal rods and discs hangs on the wall above a glossy white console table, a black sculptural head bust sits on the left side of the table next to a stack of books, a marble dome table lamp with brass base stands on the right. White paneled walls with classic molding frame the space, the console table rests on two sculptural legs covered in geometric wood marquetry with brass accents, the floor is covered in a hexagonal wood parquet pattern in cream, brown and dark walnut tones. Soft natural light falls from the left, gently reflecting off the mirror's gold surface, warm ambient light fills the hallway. Symmetrical frontal composition, viewed through an open doorway, interior photography style.", chipIDs: [], note: "A gold sunburst mirror over a marquetry console in a paneled entrance hall.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 9432908409328403),
        .init(id: "rcp.interiors.reception-oval-mirror", studio: "interiors", title: "Reception Nook, Backlit Oval", subjectExample: "A small modern reception nook, an oval backlit mirror with a thin black frame hangs on a dark textured stone wall, a potted bonsai tree with twisted trunk and green foliage sits on a light stone console table below it, three smoke-glass globe pendant lamps hang on the left in front of a mirrored wall reflecting a wood-slat corridor. Wood slat ceiling with warm cove lighting above, beige fabric-paneled wall to the left, glass door partition visible at the edge of frame. Warm backlighting glows around the mirror's edge, soft golden light from hidden ceiling coves, gentle reflections on the glass pendants. Tight vertical composition, boutique hotel lobby photography style.", chipIDs: [], note: "A backlit oval mirror on dark stone, a bonsai below, glass globe pendants.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 943321340000),
        .init(id: "rcp.interiors.lounge-mustard-velvet", studio: "interiors", title: "Lounge, Mustard Velvet", subjectExample: "A cozy lounge corner, two rounded mustard-orange velvet swivel armchairs with chrome bases face each other, a small round glass coffee table and a low marble side table sit between them, a floor lamp with a spherical white glass shade stands to the left. Behind them a large abstract map-style artwork in beige and rust tones hangs on a weathered oxidized metal-clad wall, a floating wood shelf below holds books and a dark vase with dried leaves, dark wood shelving with ceramic bowls is visible on the right, floor-to-ceiling window on the far left. Warm directional light from the floor lamp mixes with soft daylight from the window, subtle highlights on the velvet upholstery and metal wall texture. Frontal symmetrical composition, interior design magazine photography.", chipIDs: [], note: "Two mustard velvet swivel chairs facing off over a glass table.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 31343321340000),
        .init(id: "rcp.interiors.dollhouse-cutaway", studio: "interiors", title: "Dollhouse Cutaway", subjectExample: "A miniature dollhouse-style cutaway of a living room, a cream sofa with a draped throw blanket sits against a sage green wall on the right, a round arched window with wood mullions is centered above a low wood dresser holding potted plants, a white bean bag chair and small wood side table with a book sit in the corner on the left near a large rectangular window, several yellow rattan pendant lamps hang from the ceiling at different heights, light wood flooring with a striped beige rug. The room is shown as an open-topped architectural box with white exterior walls, natural bright light floods in through both windows. Isometric three-quarter view, clean architectural visualization render, miniature diorama style.", chipIDs: [], note: "An open-topped diorama of a living room, isometric and clean.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 540543321340000),
        .init(id: "rcp.interiors.openplan-beige-sectional", studio: "interiors", title: "Open-Plan, Beige Sectional", subjectExample: "An open-plan living space, a beige sectional sofa with a chaise and layered cushions curves around two round black nesting coffee tables, a black bowl with dried purple flowers sits on the smaller table, a tall floor lamp stands beside the sofa on the left. A large round textured metal disc artwork hangs on a beige wall panel, dark wood open shelving units with books and wine bottles flank the space on both sides, a kitchen bar with dark countertop, marble backsplash, bar stools and wine glasses is visible in the background, dark herringbone wood flooring with a charcoal area rug underfoot. Linear ceiling track lighting provides even overhead illumination, warm under-cabinet lighting glows in the kitchen backsplash. Wide horizontal composition, real estate interior photography.", chipIDs: [], note: "A curved beige sectional wrapping nesting tables, a kitchen bar beyond.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 32443243200),
        .init(id: "rcp.interiors.loft-chesterfield", studio: "interiors", title: "Loft Living, White Chesterfield", subjectExample: "A spacious industrial-style loft living room, a white tufted chesterfield sofa with black cushions and a draped black throw blanket, a brown leather armchair on the left, a black cube-shaped coffee table with scattered magazines and a camera on top, a gray shaggy rug on a light wood floor. Exposed red brick wall with a large black-and-white framed photograph on it, a wood beam ceiling with visible ductwork, a mezzanine level with a glass-walled wardrobe on the right, tall windows on the left, a green potted plant in the corner. Soft natural light from the windows on the left, complemented by warm spotlighting from the ceiling, gentle shadows on the brick. Wide-angle interior shot, design catalog photography, clear room perspective.", chipIDs: [], note: "A white chesterfield in a brick-and-beam loft, ductwork overhead.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 30097534320099),
        .init(id: "rcp.interiors.library-living-mustard", studio: "interiors", title: "Library Living Room", subjectExample: "An elegant library-living room, a mustard-yellow sofa with a metal frame on the left, two striped gray-brown armchairs on the right, a round gray coffee table with books and a brass bowl in the center, a light rug beneath the furniture. Tall bookshelves with dark frames and glass doors filled with books flank the fireplace, a curved metal staircase with railings leads to a second-level library on the right. A white marble fireplace in the center with an abstract geometric marble-and-brass panel above it, an ornate decorative ceiling. Ceiling spotlights aimed at the bookshelves, warm diffused light throughout the room. Symmetrical frontal composition, interior photography.", chipIDs: [], note: "A mustard sofa between full bookshelves and a marble fireplace.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 9898313),
        .init(id: "rcp.interiors.twolevel-living-kitchen", studio: "interiors", title: "Two-Level Living-Kitchen", subjectExample: "A spacious two-level living-kitchen space, a brown leather sofa with horizontal channel tufting in the center, two round black armchairs on the right, several low coffee tables of varying heights in front of the sofa, a gray rug on a concrete floor. On the left, a lit metal staircase with a bottle rack leads to an upper level with railings and a brass wall, a kitchen island with bar stools sits in the background at the center, a chain-link pendant light hangs from the ceiling. Floor-to-ceiling panoramic windows on the right overlook a forest. A dark mesh ceiling with recessed lighting, warm accent light on the brass wall contrasts with cool daylight from the windows. Shot from a slightly low angle, emphasizing the ceiling height.", chipIDs: [], note: "A channel-tufted leather sofa under a double-height space, forest through the glass.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 93029434943209),
        .init(id: "rcp.interiors.classic-navy-living", studio: "interiors", title: "Classic Room, Navy Sofa", subjectExample: "A bright living room in a classic building, a dark navy sofa with rounded curves on the right with green and gray cushions, an unusually curved wooden chair on the left, a dark chair on wooden legs nearby, a black coffee table with an abstract patterned top and sculptural pedestal legs in colored concrete. A white marble fireplace in the center with ornate molding, a colorful abstract wall sculpture above it, an ornamented molded ceiling, a large black-and-white painting on the left, a bright framed artwork on the right, a blue vase with a lily on the mantel. A brass ceiling light fixture with multiple shades, soft daylight from the window on the right falls across the floor and furniture. Natural asymmetrical composition, daytime interior photography.", chipIDs: [], note: "A curved navy sofa and sculptural chairs in a molded classic room.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 302193028403),
        .init(id: "rcp.interiors.sloped-ceiling-living", studio: "interiors", title: "Sloped-Ceiling Living Room", subjectExample: "A modern living room with a high sloped ceiling, a dark gray sectional sofa with cushions on the left, a round wooden coffee table on an ottoman base in the center, a multicolor brown-and-pink toned rug on a light floor. A vertical wood slat wall on the left, a green wood slat partition on the right with an open shelf and a TV mounted on it, a wood media console below the TV. Sliding glass doors at the back of the room open onto a garden with trees, dark curtains on either side. Two ring-shaped LED pendant lights above the sofa cast soft warm light, muted evening daylight visible outside the window. Diagonal room composition, view of the living room with the dining area visible on the right.", chipIDs: [], note: "A grey sectional under a high slatted ceiling, garden doors at the back.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 999131231000231),
        .init(id: "rcp.exteriors.glass-pavilion-autumn", studio: "exteriors", title: "Glass Pavilion in Autumn", subjectExample: "A single-story modern glass pavilion house with a flat black roof, floor-to-ceiling black-framed glass walls and sliding doors span the entire front facade, a wood deck with built-in steps leads down to a gravel courtyard, dark wood siding on the side sections of the house. Tall autumn trees with bright yellow and green maple leaves surround and overhang the structure, large moss-covered boulders rest on the gravel ground in the foreground, a small wood footbridge is visible on the left. Inside, warm interior lighting glows through the glass revealing dining chairs and furniture, dusk approaching with soft fading daylight filtering through the canopy. Symmetrical frontal composition, architectural photography, framed by overhanging branches.", chipIDs: [], note: "A flat-roofed glass pavilion glowing warm under yellow maples.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 102939364343324),
        .init(id: "rcp.exteriors.brick-stone-villa", studio: "exteriors", title: "Brick & Stone Villa", subjectExample: "A large three-story contemporary villa with white brick and black stone cladding, cantilevered upper floor with a glass balcony railing and outdoor dining set, wood slat accent panels between window bays, a covered ground-floor terrace with outdoor sofas and a fire pit area. Tiered stone steps and a wood deck lead through manicured gardens with round trimmed shrubs and white flowering bushes, a reflecting pool with steps is visible in the foreground, misty mountains rise in the background. Warm interior lighting glows from every floor at dusk, soft overcast sky light overhead, cool blue-gray tones on the stone surfaces. Elevated three-quarter view, luxury real estate photography.", chipIDs: [], note: "A three-storey villa in white brick and black stone above a reflecting pool.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 11029396454390),
        .init(id: "rcp.exteriors.black-panel-townhouse", studio: "exteriors", title: "Black-Panel Townhouse", subjectExample: "A narrow two-story modern townhouse with flat matte black facade panels, an inset second-floor balcony with a glass railing and warm glowing interior visible through large windows, a glass-paneled entry door on the ground floor lit from within. A tall black horizontal slat privacy fence and matching gate enclose the small front yard, ornamental grasses and low plantings line the concrete walkway, a large tree overhangs from the right side. Overcast bright sky above, warm interior lighting spilling out through the windows and door contrasts with the cool exterior tones, soft even daylight on the facade. Straight-on frontal composition, urban infill housing photography.", chipIDs: [], note: "A narrow black-panel townhouse, warm windows behind a slat fence.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 832183210383974),
        .init(id: "rcp.exteriors.cantilever-roof-house", studio: "exteriors", title: "Cantilevered Roof House", subjectExample: "A two-story modern house with a dramatically cantilevered flat roof extending over a glass-walled upper terrace, dark stone and beige stucco cladding, floor-to-ceiling black-framed glass walls on the ground floor opening onto a covered patio with sofas and a dining set. A stone paver pathway winds through lush landscaping with ornamental grasses, tropical shrubs and flowering plants, a black privacy fence runs along the left side, tall eucalyptus trees rise behind the house. Clear blue sky with scattered white clouds, bright midday sunlight casting sharp shadows under the roof overhang, warm interior lighting visible through the glass. Low-angle frontal composition, architectural exterior photography.", chipIDs: [], note: "A dramatic cantilevered roof over a glass upper terrace, midday shadows.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 2193032818312),
        .init(id: "rcp.exteriors.hillside-villa-dusk", studio: "exteriors", title: "Hillside Villa at Dusk", subjectExample: "A sleek multi-level modern villa built into a hillside, cantilevered concrete terraces with glass railings extend outward over the slope, floor-to-ceiling glass walls reveal illuminated interior rooms and a bathroom with a freestanding tub, an outdoor dining table and lounge chairs sit on a stone terrace shaded by small trees in planters. The house is built against a dark hillside covered in trees and shrubs, city lights and other hillside homes spread out below and into the distance, a deep orange sunset glow fades into blue twilight sky above. Warm architectural lighting illuminates the terraces and interior spaces against the darkening landscape, city skyline glittering faintly on the horizon. Elevated distant three-quarter view, luxury real estate twilight photography.", chipIDs: [], note: "A cantilevered hillside villa lit against the city at dusk.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 1, aspectH: 1, seed: 8867688328183122121),
        .init(id: "rcp.exteriors.white-villa-tropical", studio: "exteriors", title: "White Villa in the Green", subjectExample: "A modern, single-story white villa is nestled amidst a dense canopy of lush green tropical foliage under a clear blue sky. The building features a stark, minimalist architectural design with clean lines and flat surfaces; its front facade is dominated by floor-to-ceiling glass windows that reveal a glimpse of the interior, where dark furniture sits on an elevated patio. The house is positioned slightly above the surrounding vegetation, creating a sense of being integrated into yet distinct from nature. The scene is bathed in warm, golden sunlight that suggests late afternoon or early evening, casting soft shadows and highlighting the texture of the leaves. The image is rendered in a hyper-realistic, photorealistic style with high fidelity to materials—the smooth matte finish of the white walls contrasts with the organic, detailed textures of the leaves and branches. The composition uses a wide-angle perspective to emphasize the scale of the structure against the natural environment, with a shallow depth of field that keeps the house in sharp focus while softly blurring the foreground plants. There is no visible text in the image., in an industrial loft with exposed brick, black metal frames and concrete floors, strong backlight cutting through atmospheric haze, glowing rim on the subject and soft volumetric light beams, two-point perspective on the building corner, two facades receding to either side", chipIDs: [], note: "A minimalist white villa tucked into dense tropical green.", badge: .green, featured: false, tier: .klein9B, steps: 10, quality: .best, aspectW: 1, aspectH: 1, seed: 8213791239127390),
        .init(id: "rcp.cinema.cowboy-backlit-ride", studio: "cinema", title: "Cowboy, Backlit Ride", subjectExample: "A cowboy on horseback seen from behind, riding through a field of tall dry grass toward the horizon, wide-brim hat silhouetted against the sky, a second horse walking just beside him. Dense pine tree line and distant mountains framing the scene. Low sun setting directly behind the riders, strong warm orange backlight, heavy lens flare, silhouetted figures, dusty golden haze drifting through the air, scattered clouds catching the last light. Close telephoto shot, shallow depth of field, warm cinematic color grade, subtle film grain.", chipIDs: [], note: "A cowboy riding into a low backlit sun, dust in the golden haze.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .best, aspectW: 1, aspectH: 1, seed: 9887320138338173),
        .init(id: "rcp.exteriors.empty-ranch-golden", studio: "exteriors", title: "Empty Ranch, Golden Grass", subjectExample: "Empty countryside ranch property with a wooden farmhouse and a large barn, wooden livestock corrals and pens standing empty. Rows of round hay bales stacked along the field edge, an old tractor with a baler attachment parked in the yard, dirt driveway leading up to the buildings. Dry golden grassland stretching into the distance, low rolling hills, a snow-capped mountain range on the horizon under a hazy pale sky. Late afternoon overcast light, soft diffused sunlight, muted teal and orange cinematic color grade, thin atmospheric haze. Wide aerial establishing shot, anamorphic lens look, deep depth of field, film still.", chipIDs: [], note: "An empty ranch of farmhouse and barn on dry golden grassland, mountains beyond.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .best, aspectW: 1, aspectH: 1, seed: 90062130138338173),
        .init(id: "rcp.cinema.abrams-flare", studio: "cinema", title: "Anamorphic Sci-Fi Action", subjectExample: "a pilot in a sleek flight suit striding across a hangar deck toward a waiting craft, backlit by bright rig lights", chipIDs: ["pose.walking", "frame.cowboy", "lens.anamorphic", "style.scificlean", "color.coldsteel", "light.kicker"], note: "J.J. Abrams horizontal streak-flare language: a gentle glow off the brightest backlight across a cool sterile palette. 🟡 Keep console panels blank — Klein cannot render legible readouts.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9, seed: 329847937493743),
        .init(id: "rcp.cinema.aerial-battlefield", studio: "cinema", title: "Aerial Battlefield Establishing", subjectExample: "a small squad advancing in loose formation across a war-torn field, craters and smoke columns marking the ground around them", chipIDs: ["frame.establishing", "angle.aerial", "env.smokehaze", "color.bleachbypass", "style.gritwar", "lens.24mm"], note: "The bird's-eye establishing shot that sets battlefield scale before the clash, revealing choreography from above. 🟡 Keep figures small and few — dense armies of sharp individuals degrade at low steps.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9, seed: 3213123002139),
        .init(id: "rcp.cinema.dutch-chaos", studio: "cinema", title: "Dutch-Tilt Disaster", subjectExample: "a survivor scrambling through a collapsing street as smoke and dust billow around them, debris raining down", chipIDs: ["pose.midaction", "frame.full", "angle.dutch", "env.smokehaze", "color.muted", "style.cinematic"], note: "A canted horizon tips the world off-balance for pure chaos and disorientation. 🟡 Keep it to one survivor — the dust and haze hide the background so Klein never has to render dense sharp figures.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9, seed: 9338384848355),
        .init(id: "rcp.cinema.explosion-silhouette", studio: "cinema", title: "Backlit Explosion Silhouette", subjectExample: "a lone soldier sprinting away from a massive fireball erupting behind him, kit and rifle bouncing as he runs", chipIDs: ["pose.midaction", "frame.full", "angle.low", "light.hazeback", "color.tealorange", "lens.anamorphic"], note: "The signature war-poster look: the figure reads as a dark outline against a blown-out blast, so identity and hands vanish into silhouette exactly where Klein is weakest. Reliable and dramatic.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9, seed: 84032840848749),
        .init(id: "rcp.cinema.firelight-face", studio: "cinema", title: "Firelight Close-Up", subjectExample: "a soldier's face lit by the flicker of a nearby fire, jaw set, eyes fixed on something off-frame", chipIDs: ["expr.serious", "frame.closeup", "light.firelight", "color.tealorange", "lens.85mm", "angle.eye"], note: "Motivated firelight rakes one side of the face with warm flicker and a hard edge from the flames — the fear/determination beat. A tight single face keeps hands out of frame entirely, playing to Klein's strengths.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 4, seed: 9938477973434),
        .init(id: "rcp.cinema.furyroad-convoy", studio: "cinema", title: "Fury Road Amber Convoy", subjectExample: "a battered pursuit car tearing across an open desert flat, a dust plume boiling off its wheels, dead-center in frame", chipIDs: ["pose.midaction", "frame.centered", "env.desert", "color.furyamber", "lens.tele135", "light.hardsun"], note: "John Seale's Fury Road rule: subject dead-center for readability during fast cuts, hypersaturated amber sand, telephoto compression stacking the chase. A vehicle hero keeps faces and hands out of the equation entirely.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9, seed: 90921364664374),
        .init(id: "rcp.cinema.hero-lowangle", studio: "cinema", title: "Low-Angle Hero", subjectExample: "an armored warrior planted wide and still, chin raised, looming against a bright pale sky", chipIDs: ["pose.alertstand", "frame.full", "angle.wormseye", "light.rim", "color.crushedblacks", "style.cinematic"], note: "The dominance shot: an extreme worm's-eye angle makes the figure tower and read as invincible, backlit rim separating it from a blown-out sky. Classic blockbuster hero framing; a single still subject is well within Klein's reach.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 2, aspectH: 3, seed: 656378478478321),
        .init(id: "rcp.cinema.johnwick-neonoir", studio: "cinema", title: "John Wick Neon-Noir", subjectExample: "a lone gunman in a black suit walking down a rain-soaked alley at night between bare wet brick walls, the whole alley and the mirrored asphalt bathed in a soft magenta-and-cyan glow spilling from lights hidden above the frame", chipIDs: ["pose.walking", "frame.full", "env.rainyneonalley", "style.neonoir", "lens.anamorphic", "angle.eye"], note: "Dan Laustsen's magenta-and-cyan wash on wet black streets with clean wide framing. 🟡 Keep the neon as wordless abstract light strips reflected in the wet street — any implied lettering (including Japanese glyphs) garbles on Klein.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9, seed: 4893874983749372),
        .init(id: "rcp.cinema.rooftop-bluehour", studio: "cinema", title: "Rooftop Blue-Hour Standoff", subjectExample: "a lone figure in a long coat standing at the edge of a rooftop, the sprawling city skyline glittering far below", chipIDs: ["pose.alertstand", "frame.wide", "env.rooftopview", "light.blue", "lens.anamorphic", "color.coldsteel"], note: "Blue-hour twilight over a wide anamorphic city vista with a gentle horizontal glow in the skyline lights. A calm setup beat with cool, restrained cinematic tension.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9, seed: 5435983790544421),
        .init(id: "rcp.cinema.sicario-silhouette", studio: "cinema", title: "Deakins Ochre Silhouette", subjectExample: "a special-forces operator standing on a desert ridge at dusk, geared up and facing the low sun, half turned toward the horizon", chipIDs: ["pose.alertstand", "frame.wide", "light.rim", "color.muted", "lens.tele135", "angle.low"], note: "Roger Deakins' Sicario language: a backlit near-silhouette with true deep blacks and a desaturated dusty-ochre palette from one hard natural source. Restrained and expensive; the near-silhouette also hides the face, which suits Klein.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 2, aspectH: 3, seed: 1111000983747),
        .init(id: "rcp.cinema.spr-warbeach", studio: "cinema", title: "Bleach-Bypass War Grit", subjectExample: "an infantryman wading through cold surf toward a beach under fire, sand and debris flung frozen around him", chipIDs: ["pose.midaction", "frame.half", "color.bleachbypass", "lens.freezeaction", "style.gritwar", "light.overcast"], note: "The Saving Private Ryan combo: a fast-shutter freeze stops debris razor-sharp over a desaturated silver-retention grade with crushed blacks and heavy grain. Waist-up framing keeps hands manageable.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9, seed: 9382173974645741),
        .init(id: "rcp.cinemamood.altonchiaroscuro", studio: "cinemamood", title: "Alton Chiaroscuro Noir", subjectExample: "A lone trench-coated detective standing in a vast empty warehouse, a slow curl of cigarette smoke rising beside him", chipIDs: ["light.chiaroscuro", "color.bw", "light.hardsingle", "frame.negspace", "angle.low", "style.filmnoir"], note: "John Alton low-key: one hard source carves the subject out of crushed black with no fill. Reads expensive at low steps because the palette is pure monochrome contrast and the figure stays dark, sidestepping face fidelity.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 2, aspectH: 3, seed: 39837498374943),
        .init(id: "rcp.cinemamood.deakinsscifi", studio: "cinemamood", title: "BR2049 Cyan Fog Scale", subjectExample: "A tiny lone figure standing at the base of a monumental brutalist concrete wall, dwarfed by its scale", chipIDs: ["light.br2049fog", "frame.wide", "frame.centered", "style.scificlean", "frame.frameinframe", "lens.24mm"], note: "Cold hazy cyan fog with a single motivated glow and a tiny figure dwarfed by monumental architecture — Deakins BR2049 scale and isolation. Wide framing hides low-step detail in atmosphere.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9, seed: 90890808776554),
        .init(id: "rcp.cinemamood.fogsilhouette", studio: "cinemamood", title: "Backlit Fog Silhouette", subjectExample: "A lone figure in a long coat standing at the middle of a wide bridge", chipIDs: ["light.hazeback", "frame.wide", "env.foggymoor", "frame.negspace", "light.rim", "color.crushedblacks"], note: "Hard backlight rims a near-black silhouette against pale foggy ground — isolated and mysterious. Keeping the subject dark sidesteps Klein's face and hand fidelity issues; a single crushed-black grade keeps the tones clean.", badge: .green, featured: false, tier: .klein9B, steps: 15, aspectW: 16, aspectH: 9, seed: 344324423454545),
        .init(id: "rcp.cinemamood.goldenhourvista", studio: "cinemamood", title: "Golden-Hour Backlit Vista", subjectExample: "A lone rider on horseback pausing on a high ridge at sundown, overlooking a vast landscape", chipIDs: ["light.golden", "frame.establishing", "env.mountains", "color.warm", "light.rim", "lens.film35"], note: "Low magic-hour sun as backlight with glowing rim, long shadows and atmosphere catching the beams — romantic natural light that also serves a western vista.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9, seed: 123021938873987),
        .init(id: "rcp.cinemamood.horrorunderlight", studio: "cinemamood", title: "Horror Underlight Dread", subjectExample: "A pale gaunt face emerging from the darkness, eyes fixed on the camera", chipIDs: ["light.horrordread", "frame.closeup", "color.crushedblacks", "style.horror", "expr.neutral", "light.lowkey"], note: "Underlighting from below the eyeline throws shadows upward, hollowing the eye sockets into an uncanny mask. A single low practical keeps it monstrous without muddying at low steps.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 2, aspectH: 3, seed: 998087931345888),
        .init(id: "rcp.cinemamood.negfilldread", studio: "cinemamood", title: "Negative-Fill Half-Shadow", subjectExample: "an empty child's bedroom at night, a single small handprint pressed on the inside of one fogged window pane, the closet door standing just ajar into black, plain bare walls", chipIDs: ["style.horror", "light.lowkey", "color.crushedblacks"], note: "🟡 The dread is what you don't see — the ajar door and the one handprint imply a presence. No figure needed; that's the point. Keep the walls bare so nothing else latches.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.cinemamood.neonrainnoir", studio: "cinemamood", title: "Neon-Noir Rain Reflections", subjectExample: "A figure in a wet leather jacket pausing in a narrow alley of plain wet brick, the walls and puddled ground washed in a soft magenta-and-cyan glow spilling down from lights hidden above the frame", chipIDs: ["env.rainyneonalley", "style.neonoir", "color.cinestill800t", "light.neon", "frame.half", "color.crushedblacks"], note: "Magenta-and-cyan practicals bleed through rain and haze with halation glow — Refn / Blade Runner mood. 🟡 Keep signage as wordless abstract color, never lettering; Klein garbles any implied type, so the glow stays pure light.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9, seed: 983791239379),
        .init(id: "rcp.cinemamood.romancebacklight", studio: "cinemamood", title: "Golden Romance Bokeh", subjectExample: "A young woman glancing back over her shoulder with a soft smile, warm out-of-focus string-light bokeh well behind her, the glowing orbs kept soft and separate from her hair", chipIDs: ["light.rim", "lens.85mm", "color.warm", "env.bokehlights", "expr.softsmile", "style.romance"], note: "Soft warm key plus a golden hair backlight, dreamy string-light bokeh on an 85mm lens — La La Land warmth. 🟡 Keep the lights as soft out-of-focus orbs set well behind her, not sharp wires near the hair, or the strand resolves as tangled filaments over the head.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2, seed: 9965379123937933),
        .init(id: "rcp.cinemamood.tealorangesplit", studio: "cinemamood", title: "Teal-and-Orange Split", subjectExample: "A man in a dim bar leaning on the counter, a drink in front of him", chipIDs: ["color.tealorange", "light.practical", "frame.half", "light.lowkey", "angle.threequarter", "style.cinematic"], note: "Cool cyan shadows against warm orange highlights with crushed blacks — the modern cinematic split. A single motivated practical keeps the lighting logic coherent for the few-step render.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2, seed: 3213232339333),
        .init(id: "rcp.cinemamood.venetianbars", studio: "cinemamood", title: "Venetian-Blind Shadow Bars", subjectExample: "A woman in a dark room turning slowly toward the window, a lit cigarette in her hand", chipIDs: ["light.venetianbars", "color.bw", "frame.closeup", "light.lowkey", "expr.serious", "style.filmnoir"], note: "Stark cage-like shadow bars rake across face and wall — the signature noir gobo. A single lit face keeps within Klein's strengths; smoke in the beam adds cheap depth that hides low-step weakness.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2, seed: 233238884),
        .init(id: "rcp.portrait.avedon", studio: "portrait", title: "Avedon White-Ground", subjectExample: "a dancer in a simple black leotard, arms relaxed at her sides, meeting the lens with a direct gaze", chipIDs: ["light.threepoint", "frame.half", "lens.85mm", "expr.serious", "env.studio", "color.crushedblacks"], note: "Stark isolated psychological portrait on pure white with direct eye contact, Richard-Avedon style; keep the pose simple and hands resting low so Klein's weak close-up hands stay out of trouble.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5, seed: 1000002332388842),
        .init(id: "rcp.portrait.butterfly", studio: "portrait", title: "Paramount Glamour", subjectExample: "a poised woman with sculpted cheekbones and swept-back hair, chin lifted slightly toward the lens", chipIDs: ["light.butterfly", "frame.closeup", "expr.sultry", "lens.tele135", "color.bw", "env.greybackdrop"], note: "On-axis butterfly light with the symmetric under-nose shadow gives Golden-Age Hollywood modeling and 135mm keeps proportions natural; 🟡 keep the retouched-skin look honest, at this crop Klein can over-smooth without the lens detail cue.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5, seed: 1200002332388845),
        .init(id: "rcp.portrait.chiaroscuro", studio: "portrait", title: "Caravaggio Chiaroscuro", subjectExample: "an older woman with silver hair and a draped linen shawl, turned toward the light", chipIDs: ["light.chiaroscuro", "frame.closeup", "lens.85mm", "expr.neutral", "color.crushedblacks", "env.greybackdrop"], note: "Steep single side key with luminous highlights against near-black for a painterly old-master mood that Klein renders cleanly at higher steps.", badge: .green, featured: false, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 5, seed: 23129300343),
        .init(id: "rcp.portrait.clamshell", studio: "portrait", title: "Clamshell Beauty", subjectExample: "a young woman with luminous even skin and dark hair pulled back, facing the camera", chipIDs: ["light.clamshell", "frame.closeup", "expr.softsmile", "lens.85mm", "color.pastel", "env.colorseamless"], note: "Near-shadowless wraparound beauty light with twin catchlights; 🟡 at this tight beauty crop Klein tends to smooth skin waxy, so the 85mm chip is doing real work naming pores and matte texture.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5, seed: 23129300343333),
        .init(id: "rcp.portrait.highkey", studio: "portrait", title: "High-Key Headshot", subjectExample: "a confident professional in a crisp white shirt, shoulders squared to the camera", chipIDs: ["light.highkey", "frame.closeup", "lens.85mm", "expr.softsmile", "env.studio", "color.muted"], note: "Bright airy Peter-Hurley commercial headshot on pure white; the soft-smile plus an engaged direct gaze prevents Klein's default vacant stare.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 1, aspectH: 1, seed: 47397434947934),
        .init(id: "rcp.portrait.lindbergh", studio: "portrait", title: "Lindbergh Raw B&W", subjectExample: "a striking woman in a plain white shirt with windswept hair and bare unretouched skin", chipIDs: ["light.singlesoft", "frame.half", "lens.tele135", "color.bw", "expr.serious", "env.greybackdrop"], note: "Grainy cinematic black-and-white editorial in the Peter Lindbergh vein, natural minimal-makeup skin and a raw stare on a stark backdrop.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5, seed: 4739743494793443),
        .init(id: "rcp.portrait.lowkey", studio: "portrait", title: "Low-Key Character", subjectExample: "a lean musician in his thirties with tousled dark hair and stubble", chipIDs: ["light.split", "frame.closeup", "lens.85mm", "expr.serious", "color.crushedblacks", "light.lowkey"], note: "Hard split lighting on a black field drops one half of the face into deep shadow for intense character energy; a single catchlight keeps the lit eye alive.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5, seed: 3339743494793432),
        .init(id: "rcp.portrait.portra", studio: "portrait", title: "Portra 400 Film", subjectExample: "a freckled woman with loose auburn hair, seated near a bright window", chipIDs: ["light.window", "pose.lookaway", "lens.85mm", "color.portra", "frame.half", "expr.neutral"], note: "Soft north-window light with a warm-skin Portra grade and fine grain; the averted contemplative gaze from pose.lookaway reads as timeless editorial film.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 4, seed: 493490447934322321),
        .init(id: "rcp.portrait.rembrandt", studio: "portrait", title: "Rembrandt Editorial", subjectExample: "a weathered man in his sixties with a short grey beard, wearing a dark wool coat", chipIDs: ["light.rembrandt", "frame.closeup", "lens.85mm", "expr.serious", "color.crushedblacks", "env.greybackdrop"], note: "The classic illuminated triangle on the shadow cheek reads as expensive on Klein because it names a real pattern with a clear shadow signature; keep hands out of this tight crop.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5, seed: 32732733322321),
        .init(id: "rcp.portrait.rim", studio: "portrait", title: "Rim-Light Separation", subjectExample: "a tattooed man in a dark hoodie, jaw set, seen in profile", chipIDs: ["light.kicker", "frame.half", "lens.85mm", "expr.serious", "color.crushedblacks", "light.lowkey"], note: "A strip-softbox kicker carves a bright edge along the jaw and shoulder for strong subject-background separation on a dark ground; the half-body crop keeps it distinct from the tighter low-key character look.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5, seed: 3273273332232133),
        .init(id: "rcp.portrait.tealorange", studio: "portrait", title: "Cinematic Teal-Orange", subjectExample: "a rugged man in a leather jacket against a concrete wall", chipIDs: ["light.loop", "frame.half", "lens.85mm", "color.tealorange", "pose.leaning", "style.cinematic"], note: "Loop lighting with a teal-and-orange editorial grade and a movie-still cinematic feel; the leaning pose and wide frame give it the look of a film frame.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9, seed: 33232131243),
        .init(id: "rcp.peoplesociety.craftsperson", studio: "peoplesociety", title: "Craftsperson at Work", subjectExample: "A weathered craftsperson in their sixties mending a leather satchel at a cluttered wooden workbench, sleeves rolled up, absorbed in the task", chipIDs: ["env.wood", "light.overcast", "lens.50mm", "style.documentary", "color.portra", "pose.handlingobject"], note: "Environmental portrait with overcast sky-as-softbox and Portra warmth; the classic craftsperson-at-workbench look. Hands stay occupied in a natural mid-task action rather than in fine close-up, which suits Klein's weak hand fidelity.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2, seed: 3323213124332),
        .init(id: "rcp.peoplesociety.decisivemoment", studio: "peoplesociety", title: "Decisive-Moment Street", subjectExample: "A lone figure in a long coat walking through a bright shaft of sunlight against a clean shadowed wall, caught at the peak of stride", chipIDs: ["env.street", "pose.walking", "lens.deep", "light.hardsun", "style.documentary", "color.bw"], note: "Cartier-Bresson patch-of-light-and-wait: a pre-composed background completed by one figure at the peak gesture, deep-focus f/8 geometry in stark monochrome. Single subject and blank wall keep it clean for Klein.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2, seed: 33232131243322),
        .init(id: "rcp.peoplesociety.digicamparty", studio: "peoplesociety", title: "2000s Digicam Party", subjectExample: "Two friends laughing together at a house party, one caught mid-blink, wearing plain unbranded tops, a cluttered living room behind", chipIDs: ["env.livingroom", "light.flash", "expr.laughing", "frame.twoshot", "color.faded"], note: "Authentic 2000s point-and-shoot snapshot: on-camera flash, slight noise and flat imperfect color. Era cues carry the candid feel. 🟡 Keep tops plain and unbranded — graphic-tee lettering garbles on Klein; dropping the in-hand cup avoids an unresolved finger grip.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 3, seed: 1232132131243322),
        .init(id: "rcp.peoplesociety.gildenflash", studio: "peoplesociety", title: "Gilden Confrontational", subjectExample: "A startled passerby caught up close on a busy sidewalk, wide-angle inches from the face, a raw surprised expression", chipIDs: ["env.street", "lens.24mm", "light.flash", "expr.serious", "frame.closeup", "color.bw"], note: "Bruce Gilden confrontational wide-flash: harsh bare on-camera flash, blown-out foreground and dark background in gritty high-contrast monochrome. 🟡 Extreme wide-angle at very close range can distort features; embrace it as the intended raw style.", badge: .yellow, featured: false, tier: .klein9B, steps: 15, aspectW: 3, aspectH: 4, seed: 23121321312433222),
        .init(id: "rcp.peoplesociety.goldenfestival", studio: "peoplesociety", title: "Festival, After the Rain", subjectExample: "a teenager at a muddy festival grinning as she carries a friend piggyback through ankle-deep puddles, both soaked, wellies caked, tents blurred behind", chipIDs: ["style.documentary", "light.overcast", "color.faded"], note: "🟡 Mischief and mud, not the usual arms-raised euphoria — a single candid pair reads best. Keep the background crowd soft; dense figures degrade.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.peoplesociety.lindbergh", studio: "peoplesociety", title: "Lindbergh Editorial B&W", subjectExample: "a boxer between rounds slumped in the corner in a dark sports bra, cutman crouched beside her steadying her jaw with one flat hand while he presses a small swab to her brow, chest heaving, eyes half-shut with exhaustion, sweat catching the ring light", chipIDs: ["color.bw", "light.hardsingle", "frame.half"], note: "🟡 The point is real exhaustion and grit in black and white, not a blank model on grey. Hands near the face are fiddly — kept to one flat hand plus a simple swab and stepped up so fingertips stay distinct.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 5),
        .init(id: "rcp.peoplesociety.mccurrygaze", studio: "peoplesociety", title: "Market Vendor, Caught Mid-Laugh", subjectExample: "a fish-market vendor in a rubber apron throwing his head back laughing at something off-frame, wet hands raised, crates of ice and silver fish around him", chipIDs: ["style.documentary", "color.ektachrome", "frame.half"], note: "🟡 A real working person mid-laugh, not a posed stare — this deliberately avoids any famous-portrait homage. Hands near the face can distort; reroll if needed.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.peoplesociety.porchfamily", studio: "peoplesociety", title: "Kitchen Flour Fight", subjectExample: "a grandmother tossing a handful of flour with one open spread hand while a small kid cups flour to scoop back, a fine powdery haze of flour dust bursting in the air between them, both caught open-mouthed laughing, dough abandoned on the board", chipIDs: ["style.documentary", "light.window", "color.portra"], note: "🟡 A caught candid beats a posed group — hands are steered to open, separated gestures, but expect one odd hand in the flour cloud; crop or reroll if it reads wrong.", badge: .green, featured: false, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 2),
        .init(id: "rcp.peoplesociety.rembrandtchar", studio: "peoplesociety", title: "Rembrandt Character", subjectExample: "A grizzled fisherman with a deeply lined face and a wool cap, turned three-quarters toward a single high window", chipIDs: ["light.rembrandt", "angle.threequarter", "frame.closeup", "color.crushedblacks", "expr.serious", "lens.85mm"], note: "Single-source Rembrandt chiaroscuro with the signature lit cheek triangle, painterly and dramatic. One strong motivated light and a disciplined dark palette read as expensive in Klein.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 4, seed: 39213287308403),
        .init(id: "rcp.peoplesociety.wesanderson", studio: "peoplesociety", title: "Wes Anderson Overloaded Cart", subjectExample: "a bellhop in a mustard uniform pushing a brass luggage cart stacked far too high with mismatched suitcases, one small dog perched on top, down a symmetrical pastel corridor", chipIDs: ["frame.centered", "color.pastel", "light.softbox"], note: "🟡 The comedy is the absurd overloaded cart and the calm dog, not the man's face — let him look faintly resigned. Keep suitcase labels blurred; Klein garbles text.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.product.backlitbeverage", studio: "product", title: "Backlit Glowing Beverage", subjectExample: "a sweating pint of amber lager, foam collar half-collapsed, set on a scratched pub bar with a blurred beer tap glowing behind it", chipIDs: ["light.hazeback", "env.wood", "color.warm"], note: "🟡 Keep any bar signage or tap badges out of focus — Klein garbles small text and logos. The condensation and the used bar surface are what sell it.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.product.chromebrightfield", studio: "product", title: "Bright-Field Chrome / Jewelry", subjectExample: "a scratched vintage dive watch with a clean unmarked matte dial on a diver's tanned wrist, salt still drying on the steel, a hard raking light catching the worn bezel knurling", chipIDs: ["light.brightfield", "obj.lifestyle", "lens.macro100"], note: "🟡 Wear, salt and a real wrist give the watch character a blank dial can't. Keep the dial unmarked and let the drama live in the knurled bezel and raking light, not in numerals.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.product.darkfieldglass", studio: "product", title: "Dark-Field Glass Glow", subjectExample: "a whiskey tumbler the instant a single ice cube drops in, splash frozen mid-air, amber liquid and a curl of orange peel catching a single hard light on dark slate", chipIDs: ["light.darkfield", "env.slatesurface", "color.crushedblacks"], note: "🟡 The frozen splash gives the glass a reason to exist. A fast-shutter freeze look keeps the droplets crisp; reroll if the splash smears.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5),
        .init(id: "rcp.product.flatlay", studio: "product", title: "Editorial Flat Lay", subjectExample: "a top-down still life of a half-eaten croissant, a spilled espresso ring, a worn paperback lying face-down with its plain unmarked cover up and a single pair of reading glasses on a pale marble tabletop", chipIDs: ["obj.flatlay", "angle.over", "light.window"], note: "🟡 The half-eaten, spilled, mid-read clutter tells a story a tidy EDC lay can't. The book sits face-down with a plain unmarked cover; Klein garbles any print.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 1, aspectH: 1),
        .init(id: "rcp.product.gradientcosmetic", studio: "product", title: "Color-Pop Cosmetics", subjectExample: "a glossy lipstick bullet standing upright, its cap removed beside it", chipIDs: ["style.product", "obj.pedestal", "light.gelwash", "env.gradientmesh", "color.vibrant", "frame.centered"], note: "Deep-purple-to-pink gel-lit gradient for a vibrant WWP-beauty cosmetics look, product crisply lit in front. Bold saturated color-pop; keep the bullet and base unbranded.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 4, seed: 19384873497745),
        .init(id: "rcp.product.levitation", studio: "product", title: "Hero on Wet Slate", subjectExample: "a single unbranded running sneaker with a chunky sculpted sole, standing planted on dark wet slate, a crisp clean mirror reflection pooling beneath it, presented as a bold hero product with strong glossy highlights raking along the upper", chipIDs: ["obj.threequarter", "env.wetslate", "light.stripedge", "light.matchedshadow", "angle.hero", "color.steelcool"], note: "Shoe stands planted on wet slate with a clean mirror reflection beneath — the reflection gives it the same lifted hero presence without asking Klein to float an object in empty air. Low hero angle for stature, a vertical strip highlight down the upper, cool steel palette. Keep it unbranded so there's no logo to mangle.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 4, seed: 223848734977458),
        .init(id: "rcp.product.lowkeyperfume", studio: "product", title: "Low-Key Luxury Hero", subjectExample: "a faceted glass perfume bottle with a heavy metal cap, glossy amber liquid inside", chipIDs: ["style.product", "obj.pedestal", "light.stripboxrake", "light.lowkey", "color.crushedblacks", "lens.medformat"], note: "Apple-style product-on-black: a single graduated stripbox rakes the glossy surface for a moody, expensive perfume look. Keep the bottle unlabeled — 🟡 Klein garbles any engraved or printed brand text.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 4, seed: 38487349774580),
        .init(id: "rcp.product.macro", studio: "product", title: "Luxury Macro Detail", subjectExample: "a gold ring with a faceted emerald, extreme close-up on the stone facets and fine metal engraving", chipIDs: ["style.product", "frame.xclose", "lens.macro100", "light.beautydish", "env.slatesurface", "color.crushedblacks"], note: "1:1 magnification, tack-sharp gem facets and engraving with soft diffused light avoiding harsh glare. A focus-stacked craftsmanship close-up — no text surface, so Klein stays clean.", badge: .green, featured: false, tier: .klein9B, steps: 20, aspectW: 1, aspectH: 1, seed: 1184872139774580),
        .init(id: "rcp.product.splash", studio: "product", title: "High-Speed Liquid Splash", subjectExample: "a frosted plain unbranded beverage can, smooth blank unmarked surface, surrounded by a frozen crown of splashing water and suspended droplets", chipIDs: ["style.product", "light.splashfreeze", "lens.freezeaction", "env.gradientvoid", "color.vibrant"], note: "Razor-sharp crystalline droplets frozen mid-air. 🟡 Keep the can fully blank and unbranded — any implied logo or secondary text garbles on Klein; very dense fine spray can smear.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 4, seed: 2323721397745803),
        .init(id: "rcp.brand.dog-couch-guilt", studio: "brand", title: "The Guilty Look", subjectExample: "a big dog caught on the forbidden sofa, one ear down and eyes rolled up in pure guilt, a chewed slipper beside it, warm afternoon living-room light", chipIDs: ["env.livingroom", "light.golden", "lens.50mm"], note: "Humor from a real situation — the guilty side-eye is the whole joke, no straight faces.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.brand.espresso-crema-thumbprint", studio: "brand", title: "The Barista's Thumbprint", subjectExample: "a small ceramic espresso cup, hazel crema still settling, a barista's thumbprint smudged on the warm saucer beside a bent spoon on a morning café counter", chipIDs: ["env.cafe", "light.window", "lens.macro100"], note: "Desire lives in the smudge — the used thumbprint says a human just made this, not a catalog cutout.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.brand.ev-charging-frost", studio: "brand", title: "First Cold Morning", subjectExample: "an electric car charging in a suburban driveway at dawn, a thin skin of frost on the windshield, breath-fog and blue twilight, the charge-port light glowing soft green", chipIDs: ["env.housefacade", "light.blue", "style.automotive"], note: "The frost and single green glow give a real quiet morning — a specific moment, not a glossy turntable car ad.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.brand.headphones-subway-eyesclosed", studio: "brand", title: "Gone Somewhere Else", subjectExample: "a commuter on a subway platform, eyes closed and faintly smiling inside their headphones, oblivious to the blurred rush around them, cool fluorescent light", chipIDs: ["env.subwayplatform", "expr.softsmile", "lens.panblur"], note: "🟡 The streaked background crowd is intended — keep surrounding figures soft; sharp dense crowds degrade.", badge: .yellow, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.brand.kid-astronaut-cardboard", studio: "brand", title: "Cardboard Mission Control", subjectExample: "a small kid in a cardboard-box helmet, tongue out in concentration, steering an imaginary console with crayon dials taped on, afternoon light through a messy playroom", chipIDs: ["env.kidsroom", "light.window", "style.documentary"], note: "The total focus of a child taking pretend dead-seriously is the charm — real concentration, not mugging for camera.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.brand.mechanic-grin-grease", studio: "brand", title: "The Grease-Streaked Grin", subjectExample: "a woman mechanic mid-laugh, a black grease streak across her cheekbone, wiping her hands on a rag, caught in the middle of a joke she just told", chipIDs: ["env.machineshop", "expr.laughing", "light.singlesoft"], note: "The grease and the laugh make it a real caught moment — a genuine joke, not a posed portrait.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.brand.olive-oil-villa-pour", studio: "brand", title: "The Careless Pour", subjectExample: "green olive oil poured a little too generously over torn bread on a sun-baked villa table, one drip running down the loaf, harsh Mediterranean noon light and hard shadows", chipIDs: ["env.villa", "light.hardsun", "color.ektachrome"], note: "The overpour and the runaway drip make it appetizing and human — generosity, not a measured styling shot.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.brand.perfume-implied-curtain", studio: "brand", title: "The Feeling of Morning Air", subjectExample: "a woman alone on a wide dawn beach, framed from the chest up in soft backlit silhouette as a low bank of sea-fog rolls in off the water, her face half-turned into the pale rising light, hair drifting in the breeze, one hand resting lightly at her collarbone, calm and unhurried", chipIDs: ["env.beachdawn", "light.hazeback", "color.pro400h"], note: "Mood photography — the fragrance is the feeling of cool dawn air and sea-fog on skin, not a bottle on a shelf; the whole ad is the breath of the morning.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5),
        .init(id: "rcp.brand.sneaker-scuffed-victory", studio: "brand", title: "Scuffed, Not Pristine", subjectExample: "a single running sneaker mid-air over a rain-puddle, one white toe already scuffed grey and a lace flicking loose, a spray of water frozen off the sole", chipIDs: ["env.rainyneonalley", "lens.freezeaction", "color.cinestill800t"], note: "🟡 Keep brand text off the shoe — small logos and lettering on the sole tend to smear at speed.", badge: .yellow, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.brand.watch-wrist-office", studio: "brand", title: "Checked in a Meeting", subjectExample: "a wristwatch glanced at under a shirt cuff during a boring meeting, the hand relaxed on a wooden table, a coffee ring and a doodled notepad just in frame", chipIDs: ["env.openoffice", "light.window", "lens.tele135"], note: "Desire through context — the watch is worn and lived-with, not isolated on velvet.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.automotive.badge-macro-chip", studio: "automotive", title: "The chipped badge", subjectExample: "An extreme macro of a weathered enamel bonnet badge, a real chip in the paint catching the light, fine swirl marks in the clearcoat around it, a bead of morning dew clinging to the lower edge", chipIDs: ["lens.macro100", "light.window", "color.muted"], note: "Product desire through honest wear: the chip and the dew make it a real, owned object. Swap for any emblem, hood ornament, or grille detail. 🟡 The badge lettering may distort.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 1, aspectH: 1),
        .init(id: "rcp.automotive.desert-heat-shimmer", studio: "automotive", title: "Heat off the highway", subjectExample: "A dusty pickup shot from far down an empty desert highway, the whole truck warping in the heat shimmer rising off the tarmac, a single crow lifting off the roadside, high hard noon sun", chipIDs: ["style.western", "light.hardsun", "color.technicolor"], note: "The place and the heat are the subject; the truck is almost a mirage. Real midday harshness, no golden-hour crutch. Swap the vehicle. 🟡 Don't expect readable road signs.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.automotive.drive-in-nostalgia", studio: "automotive", title: "Drive-in, tailgate down", subjectExample: "A couple on a pile of blankets in the open bed of a pickup at a drive-in cinema at dusk, the projector's beam cutting the dark above them, the truck's paint catching the flickering screen light, warm and grainy", chipIDs: ["style.romance", "color.cinestill50d", "light.practical"], note: "A quiet, tender moment where the truck is the setting for a memory. The flickering screen light is the one real touch. Swap the couple and vehicle. 🟡 The cinema screen image and marquee text will be abstract, not readable.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.automotive.ferry-deck-fog", studio: "automotive", title: "Car deck, dawn fog", subjectExample: "A lone unbranded estate car parked on the open steel deck of a ferry at dawn, sea fog rolling past, tie-down chains hooked from the car's tow eyes to the deck lashing rings, a gull perched on the roof, cold flat northern light", chipIDs: ["style.cinematic", "color.coldsteel", "light.overcast"], note: "A real place and a real cold morning, not a studio. The gull is the accident that makes it a photograph. Swap the car and vessel. 🟡 Any ferry signage will render as gibberish.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.automotive.first-car-keys", studio: "automotive", title: "First set of keys", subjectExample: "A teenager sitting on the open boot sill of a battered first car in a plain unbranded supermarket car park, dangling the keys and laughing in disbelief, a friend half-in-frame filming on a phone, flat overcast light", chipIDs: ["style.documentary", "light.flash", "color.pro400h"], note: "An actual human milestone with real disbelieving joy, not a posed portrait. Direct flash gives it a snapshot honesty. Swap the teen and car. 🟡 Keep the car park plain and unbranded — storefront signage garbles on Klein; the phone screen won't render legibly either.", badge: .yellow, featured: true, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.automotive.mechanic-underneath", studio: "automotive", title: "On the creeper", subjectExample: "A woman mechanic on a creeper rolling out from under a lifted sedan, grease on her forearm, wiping her face with the back of a gloved hand, work-lamp glare and oil sheen on the concrete", chipIDs: ["style.documentary", "light.practical", "color.faded"], note: "The person who keeps the car alive, caught mid-job. Motivated work-lamp light, no studio polish. Swap the mechanic and car. 🟡 Fine tool text and gauge faces won't read cleanly.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.automotive.rally-cabin-caught", studio: "automotive", title: "Co-driver's laugh", subjectExample: "Inside a mud-spattered rally car mid-stage, the co-driver caught mid-laugh in the passenger seat, one gloved hand resting flat on a blank unmarked page of pace notes on his knee, dust light streaking through the cracked window, the cabin blurred with speed", chipIDs: ["style.documentary", "lens.panblur", "color.bleachbypass"], note: "The joy inside the machine instead of the machine itself. Panning blur sells the speed. Swap the crew and car. 🟡 One gloved hand and exterior decals can still warp or garble — keep the pace-note page and door blank.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.automotive.snow-plume-backlit", studio: "automotive", title: "Backlit snow spray", subjectExample: "An off-roader powering through fresh snow on a mountain track, a plume of powder kicked up and lit to glowing white by the low sun behind it, frozen crystals hanging in the air, a low wide angle from the snowbank", chipIDs: ["light.rim", "color.cool", "style.cinematic"], note: "A backlit powder plume with the crystals frozen and glowing, the whole frame built around one burst of motion. Swap the vehicle. 🟡 Fine crystal detail is where 9B is strongest, so lean into it.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.automotive.wash-day-dad", studio: "automotive", title: "Saturday wash-day", subjectExample: "A middle-aged man in socked feet and rolled jeans grinning as he hoses down his aging hatchback on a suburban driveway, soap sliding off the hood, a kid's bike dropped on its side in the background", chipIDs: ["style.documentary", "color.portra", "light.golden"], note: "A car photo that's really about the guy who loves it. Late-day driveway light plus a genuine grin. Swap the car and the man freely. 🟡 Keep the license plate out of frame or expect garbled text.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.automotive.wet-night-neon", studio: "automotive", title: "Kerbside, rain, neon", subjectExample: "A sports coupe pulled up to a rain-slicked kerb at night, a takeaway shopfront's neon glow bleeding cyan and magenta into the puddle beneath it, wipers stopped mid-sweep, a figure hurrying past out of focus", chipIDs: ["style.neonoir", "color.cinestill800t", "light.neon"], note: "Neo-noir but anchored to a real wet street and a passing stranger, not a clean render. CineStill halation glows around the signs. Swap the car and street. 🟡 Neon glow and the plate will read as color and light, not legible text.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.industry.apprenticelaugh", studio: "industry", title: "The Botched First Weld", subjectExample: "a young apprentice cracking up at his own lopsided practice weld, one gloved hand resting flat on the bench, while an older welder stands back grinning and shaking his head, sparks still fading nearby", chipIDs: ["style.documentary", "light.practical", "color.portra"], note: "Real workshop humor from a genuine moment, not a posed grin. 🟡 Keep it a candid mid-distance two-shot with the hands apart and resting, not meeting over the sparks — two clasped gloved hands at the focal point fuse; don't go tight on both mouths.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.industry.cleanroomamber", studio: "industry", title: "Lithography Amber", subjectExample: "a single technician in a white hooded cleanroom coverall reflected in the glossy floor of a semiconductor fab, the whole room drowned in monochromatic yellow lithography light", chipIDs: ["light.gelwash", "style.scificlean", "frame.negspace"], note: "The amber safelight is non-negotiable mood; keep it truly monochromatic. 🟡 Describe the suit as a hooded coverall, never 'bunny suit', or the model draws literal ears; the face-shield reflection and any equipment labels stay unreliable — hide the face behind glare.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.industry.foremanwindow", studio: "industry", title: "Foreman at the Window", subjectExample: "a grey-haired foreman leaning on a mezzanine rail looking down over her shift, soft dusty window light from the side, a faint tired satisfaction on her face", chipIDs: ["light.window", "frame.half", "color.faded"], note: "A quiet, specific expression carries it — tired satisfaction, not intensity. 🟡 Background workers should stay small and soft; distant faces will smear.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.industry.oneworkerbigline", studio: "industry", title: "One Human, Endless Line", subjectExample: "a lone maintenance tech in a faded blue jumpsuit crouched low with a thermos in one steady hand at the foot of a half-mile automotive body line, everything else empty on the night shift", chipIDs: ["frame.establishing", "light.practical", "color.faded"], note: "The scale gag lands because the human is doing something small and mundane. 🟡 Keep the person mid-ground, not distant, and any painted line markings will smear — let the empty line recede cleanly.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 16, aspectH: 9),
        .init(id: "rcp.industry.paynesymmetry", studio: "industry", title: "Head-On Machine, One Color", subjectExample: "a vintage bottle-capping machine shot dead-center and symmetrical, a single run of smooth unbranded vivid orange caps held in its stainless jaws mid-line, everything else steel-grey", chipIDs: ["frame.centered", "lens.largeformat", "color.coldsteel"], note: "Christopher Payne discipline: perfect symmetry, one production color doing all the drama. 🟡 Keep the hero run of caps clearly seated in the jaws and centered — repeated small parts can duplicate oddly at the edges.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 3),
        .init(id: "rcp.industry.qcglove", studio: "industry", title: "The Held Part", subjectExample: "a gloved thumb and two fingers pinching the edge of a single freshly-machined titanium turbine blade toward a bench lamp, natural hand proportions, fine tool marks and one bright burr catching the light, an oil-smudged fingertip", chipIDs: ["lens.macro100", "light.practical", "color.coldsteel"], note: "Desire lives in the tool marks and the smudge, not a clean cutout. 🟡 A visible hand can warp fingers — kept to a simple three-finger pinch, mostly cropped, at higher steps.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 5),
        .init(id: "rcp.industry.rainyyardtruck", studio: "industry", title: "Loading Dock, Blue Hour", subjectExample: "a plain unmarked box truck backed to a loading dock at blue hour, its interior light spilling warm onto the wet concrete, a driver's silhouette pulling the door", chipIDs: ["light.blue", "style.cinematic", "color.cinestill800t"], note: "The warm dock light against cold twilight does the mood. 🟡 Keep the truck unmarked; logos, plates and dock numbers will render as garble.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.industry.textilecolor", studio: "industry", title: "The Thread Wall", subjectExample: "a mill worker's hand resting flat against a wall of hundreds of cones of vivid colored thread, thumb and one finger lightly drawing a single cone forward, warm side light raking the fibers, relaxed natural hands with natural proportions", chipIDs: ["lens.macro100", "light.dappled", "color.technicolor"], note: "Repetition plus one broken pattern (the pulled cone) makes it read as authored. 🟡 The hand is at the focal point — keep it a simple flat rest with one clear finger drawing a cone forward so digits stay countable; massed identical cones can still duplicate oddly far back.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 2),
        .init(id: "rcp.industry.warehousevanish", studio: "industry", title: "The Aisle That Never Ends", subjectExample: "a towering warehouse aisle of pallet racks converging to a single vanishing point, one forklift parked partway down the row with its amber beacon glowing in the cool overhead fluorescents", chipIDs: ["angle.onepoint", "light.practical", "color.coldsteel"], note: "Straight verticals and a true vanishing point sell the depth. 🟡 Barcode labels, shelf numbers and box printing will be gibberish — lean on shape and repetition, not readable text.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.interiors.bathroom-fogged-mirror", studio: "interiors", title: "Bathroom, mirror still fogged", subjectExample: "A luxurious stone bathroom just after a hot shower — the mirror fogged at the edges, a single soft irregular hand-wipe cleared through the fog, a towel dropped over the tub's rim, steam softening the brass fixtures of a freestanding tub with one floor-standing filler", chipIDs: ["env.bathroom", "light.window", "color.softmatte"], note: "🟡 The soft hand-wipe on the fog is the human trace that sells it. Reflections in the cleared glass may render loose or doubled — keep the mirror angled away from busy detail.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5),
        .init(id: "rcp.interiors.cafe-window-rain", studio: "interiors", title: "Cafe, rain on the window", subjectExample: "A cozy corner cafe seen from inside on a rainy afternoon, the window beaded and streaked with rain, warm interior lamplight glowing against the grey street blurred beyond the glass", chipIDs: ["env.cafe", "light.practical", "color.faded"], note: "The rain-beaded glass and the warm-versus-grey contrast make the warmth feel earned. Shot from the inside looking out, not the tidy hero angle.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.interiors.hotellobby-lowangle", studio: "interiors", title: "Hotel lobby, from a low seat", subjectExample: "A grand hotel lobby framed low from a lounge chair's height, one tall lamp glowing warm in the foreground corner and the reception receding softly beyond, single-temperature evening light", chipIDs: ["env.hotellobby", "angle.low", "light.practical"], note: "Shot from where you'd actually be sitting, not from a floating eye-level tripod — the low chair-height angle gives the space its scale.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.interiors.loft-corner-dust", studio: "interiors", title: "Industrial loft, dust in the shaft", subjectExample: "An industrial loft corner where hard afternoon sun cuts a sharp diagonal through a tall window, dust drifting visibly in the beam, exposed brick and a black steel frame receding into shadow", chipIDs: ["env.loft", "angle.twopoint", "light.hazeback"], note: "The visible dust in the light shaft turns a corner into a moment. Two-point perspective keeps the verticals honest.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.interiors.stairwell-lookup", studio: "interiors", title: "Stairwell, looking straight up", subjectExample: "A modern spiral stairwell shot straight up from the ground floor, the coiling rail and treads spiraling toward a bright skylight far above, soft daylight falling down the well", chipIDs: ["env.contemporaryluxe", "angle.wormseye", "light.window"], note: "The worm's-eye view up the spiral turns architecture into a graphic coil — an angle nobody stands at by default. Swap the stair style to fit your building.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5),
        .init(id: "rcp.exteriors.twilight-facade-oneroom", studio: "exteriors", title: "House facade, one room lit", subjectExample: "A modern house facade at deep twilight where only one upstairs window glows warm and the rest of the house is dark blue — a single life visible inside the sleeping shell", chipIDs: ["env.twilighthouse", "light.blue", "color.cinestill800t"], note: "Only one lit window, not the whole glowing dollhouse — it tells a smaller, truer story. CineStill's halated glow around the light sells the dusk.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.gameconcept.boss-scale", studio: "gameconcept", title: "Canyon scale silhouette", subjectExample: "a lone hiker standing small and still at the foot of an immense sandstone canyon wall, seen worm's-eye from the ground looking steeply up the towering striated rock, the figure a dark silhouette dwarfed by the cliff, shafts of sunlight breaking through drifting dust high above", chipIDs: ["angle.wormseye", "light.godrays", "color.crushedblacks"], note: "A lone human dwarfed by a real towering canyon wall sells overwhelming scale better than any monster — the awe comes from the rock and the light shafts. Figure kept small and in silhouette, so anatomy never has to hold up.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 9, aspectH: 16),
        .init(id: "rcp.gameconcept.creature-molting", studio: "gameconcept", title: "Grounded creature reference", subjectExample: "a six-legged tundra grazer mid-molt, patches of old chitin flaking off fresh soft plating, a raven-sized companion bird for scale, rim-lit on neutral grey", chipIDs: ["pose.alertstand", "light.rim", "env.greybackdrop"], note: "Real animals molt and carry parasites — that's what sells believable anatomy. 🟡 The scale bird helps but Klein may fuse it into the creature; keep them clearly separated.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.gameconcept.env-fogbridge", studio: "gameconcept", title: "Environment concept, dawn fog", subjectExample: "a rope-and-plank bridge vanishing into valley fog, one plank missing near the far end, warm lantern glow on the near posts fading to cold grey depth", chipIDs: ["frame.establishing", "light.golden", "color.muted"], note: "Atmospheric perspective plus a single missing plank gives the place a story. 🟡 Deep fog helps Klein hide detail it can't resolve — lean into it.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.gameconcept.interior-questroom", studio: "gameconcept", title: "Quest-room interior cutaway", subjectExample: "a smuggler's back-room mapped as a dollhouse cutaway from above, an overturned chair and a still-steaming teacup showing someone just left in a hurry", chipIDs: ["angle.cutaway", "light.practical", "color.warm"], note: "The steaming cup and toppled chair tell a story the level designer can read instantly. 🟡 The cutaway keeps geometry legible but small props may blur — block them in loosely.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 3),
        .init(id: "rcp.gameconcept.inventory-relic", studio: "gameconcept", title: "Inventory relic icon", subjectExample: "a chipped obsidian compass whose needle spins wrong, resting on a scrap of oiled leather, single hard raking light catching the fingerprint smudges on the glass", chipIDs: ["frame.insert", "light.hardsingle", "env.slatesurface"], note: "Fingerprint smudges and a wrong-spinning needle make a game object feel handled and cursed. 🟡 Fine engraved runes on the rim will be illegible — keep them abstract.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 1, aspectH: 1),
        .init(id: "rcp.gameconcept.keyart-rainhold", studio: "gameconcept", title: "Cinematic key art moment", subjectExample: "a lone knight sheltering a guttering torch from sideways rain under a broken gate, backlit by lightning, one gauntlet cupping the flame", chipIDs: ["style.cinematic", "light.hazeback", "lens.anamorphic"], note: "A single quiet gesture inside chaos beats a generic sword-raise. 🟡 Klein bloom around the flame is nice but the torch shape may wobble — it's key art, not a prop sheet.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 16, aspectH: 9),
        .init(id: "rcp.gameconcept.mech-cooldown", studio: "gameconcept", title: "Hard-surface mech, between fights", subjectExample: "a hulking salvage mech kneeling on one knee, venting steam from a shoulder port, coolant streaking the scorched panel paint, raking light across every panel cut-line", chipIDs: ["angle.low", "light.kicker", "env.gradient"], note: "The steam vent makes it read as a caught moment, not a showroom render. 🟡 Fine greeble text and serial stencils will come out as gibberish — paint over them.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.gameconcept.stylized-cel-hero", studio: "gameconcept", title: "Stylized cel hero splash", subjectExample: "a rooftop courier girl skidding to a stop, scarf and delivery bag snapping forward past her, drawn as a bold shonen action cel with hard speed lines", chipIDs: ["style.shonen", "pose.midaction", "color.vibrant"], note: "Committing fully to one cel style makes it look authored, not a rendered default. 🟡 Keep the pose to one figure — multiple cel characters drift in proportion.", badge: .green, featured: true, tier: .klein9B, steps: 14, aspectW: 2, aspectH: 3),
        .init(id: "rcp.gameconcept.turnaround-mudlark", studio: "gameconcept", title: "Character turnaround sheet", subjectExample: "a swamp-witch bounty hunter in a mud-caked oilcloth coat, one boot heel worn through, front three-quarter and rear views side by side on flat grey", chipIDs: ["angle.threequarter", "env.greybackdrop", "light.threepoint"], note: "Production turnaround for modelers. 🟡 Klein won't hold the two views perfectly identical face-to-face; treat callout text as placeholder scribble, retype real labels.", badge: .yellow, featured: false, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9),
        .init(id: "rcp.gameconcept.villain-vanity", studio: "gameconcept", title: "Villain portrait, off-guard", subjectExample: "a war-scarred duchess caught mid-laugh at her own cruel joke, adjusting a cracked monocle, firelit from a low practical lamp against deep shadow", chipIDs: ["frame.closeup", "expr.laughing", "light.firelight"], note: "A genuine laugh reads more menacing than the default scowl. 🟡 Klein handles the single face well; the cracked monocle glass may not stay consistent across renders.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.nature.aspen-infrared", studio: "nature", title: "Aspen grove, surreal register", subjectExample: "a dense aspen grove in high summer rendered in surreal infrared, foliage glowing soft pink-white, pale trunks stark against a near-black sky, one clean empty shaft of light falling through the canopy", chipIDs: ["env.forest", "color.infrared", "light.hazeback"], note: "A committed stylistic choice — infrared makes a familiar grove read alien and authored. Lean all the way in, and keep the light shaft clean and empty.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5),
        .init(id: "rcp.nature.autumn-dappled-path", studio: "nature", title: "Autumn woods, dappled trail", subjectExample: "a narrow dirt trail curving into an amber autumn wood, fresh-fallen leaves still bright on the path, sunlight breaking into shifting coins of light across the ground", chipIDs: ["env.autumnwood", "light.dappled", "color.warm"], note: "The just-fallen leaves date the moment to this exact week. Let the dappled light fall unevenly — don't smooth it out.", badge: .green, featured: false, tier: .klein9B, steps: 14, aspectW: 4, aspectH: 3),
        .init(id: "rcp.nature.beach-dawn-footprints", studio: "nature", title: "Beach dawn, a single track", subjectExample: "a wide empty beach at first pastel light, one line of small three-toed seabird tracks crossing wet sand toward the water, each print a delicate splayed arrow, the tide already erasing the far end of the trail", chipIDs: ["env.beachdawn", "light.blue", "color.pro400h"], note: "The tide erasing the tracks is the story — one trail, half-gone. Keep it minimal. Describe the bird tracks specifically so they read as small splayed prints, not human feet.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9),
        .init(id: "rcp.nature.bluehour-tidepool", studio: "nature", title: "Blue-hour coast, one still pool", subjectExample: "a wet basalt shelf at low tide during blue hour, the whole twilight sky mirrored in a single glassy tide pool, a lone barnacled rock breaking the reflection off-center", chipIDs: ["env.coastalcliffs", "light.blue", "color.coldsteel"], note: "The whole shot lives on that off-center rock — resist centering it. Cool, quiet, almost no contrast.", badge: .green, featured: false, tier: .klein9B, steps: 14, aspectW: 3, aspectH: 2),
        .init(id: "rcp.nature.godray-larch", studio: "nature", title: "Dawn god-rays through pines", subjectExample: "a stand of tall pines on a misty ridge at first light, low sun firing hard shafts between the trunks, one bright beam catching a slow-drifting curtain of woodsmoke haze", chipIDs: ["env.mistpine", "light.hazeback", "color.ektachrome"], note: "The haze is the subject, not the trees. Shoot straight into the sun so the beams read.", badge: .green, featured: true, tier: .klein9B, steps: 14, aspectW: 3, aspectH: 2),
        .init(id: "rcp.nature.snow-treeline-graphite", studio: "nature", title: "Snow squall at the treeline", subjectExample: "the ragged edge of the treeline in a mountain snow squall, near black spruce sharp and frosted, the ranks behind dissolving into falling snow until only faint gray suggestions remain", chipIDs: ["env.snowypeaks", "color.bw", "light.overcast"], note: "Falling snow does the depth work — front trees crisp, back trees ghosts. High-contrast mono suits the mood.", badge: .green, featured: false, tier: .klein9B, steps: 14, aspectW: 4, aspectH: 5),
        .init(id: "rcp.nature.storm-cliff-squall", studio: "nature", title: "Coast under a passing squall", subjectExample: "a headland the instant a rain squall sweeps past, a bright shaft of sun punching through the retreating cloud to spotlight one patch of churning sea, the cliffs still dark and wet", chipIDs: ["env.coastalcliffs", "light.spotlight", "color.crushedblacks"], note: "The sunbreak on one patch of sea is the whole photograph — everything else stays dark and threatening. Weather is the subject.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.nature.tele-ridgelines", studio: "nature", title: "Telephoto fog-stacked ridges", subjectExample: "receding mountain ridgelines at dawn compressed into flat tonal layers, dark near ridge fading to the palest far one, a thin river of valley fog threading between two of the middle planes", chipIDs: ["env.foggymoor", "lens.tele135", "color.muted"], note: "Telephoto compression does the work — flatten the planes, let tone carry depth. The fog river is the one living element.", badge: .green, featured: true, tier: .klein9B, steps: 14, aspectW: 16, aspectH: 9),
        .init(id: "rcp.nature.velvia-ridge-flare", studio: "nature", title: "Golden-hour ridgeline sidelight", subjectExample: "a spine of alpine ridges raked by the last low sun, long shadows off every fold, a scatter of lupine going translucent where the light passes through the petals in the near foreground", chipIDs: ["env.snowypeaks", "light.golden", "color.technicolor"], note: "Backlit petals are the one caught detail — get low so the sun passes through them. Rich color without going radioactive.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9),
        .init(id: "rcp.nature.waterfall-portra", studio: "nature", title: "Shaded waterfall, dripping ferns", subjectExample: "a small forest waterfall in flat overcast shade, water pulled to soft silk by a long exposure, rain-heavy ferns bowed low and dripping in the foreground, deep saturated moss", chipIDs: ["env.waterfall", "light.overcast", "color.portra"], note: "Overcast is the correct light for water — no blown highlights. The bowed dripping ferns say it just rained.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.travel.backlit-temple-monk", studio: "travel", title: "Incense Against the Sunset", subjectExample: "a temple silhouette black against a vivid pink-orange sky, a thin ribbon of incense smoke catching the last light, one monk's small figure crossing the courtyard", chipIDs: ["light.rim", "env.smokehaze", "color.warm"], note: "The incense ribbon is the one caught, unrepeatable thing; the rim-lit silhouette handles the rest.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 2, aspectH: 3),
        .init(id: "rcp.travel.coastroad-phonesnap", studio: "travel", title: "Grabbed From the Car", subjectExample: "a coastal switchback road seen from a moving car window, slightly tilted, the wing-mirror in the corner and a bug-smear on the glass catching the low golden light", chipIDs: ["lens.phonesnap", "light.golden", "color.fadedpostcard"], note: "The tilt, the mirror and the dirty glass make it feel truly snapped on a road trip, not droned. One honest imperfection carries it.", badge: .green, featured: true, tier: .klein9B, steps: 14, aspectW: 16, aspectH: 9),
        .init(id: "rcp.travel.desert-window-driver", studio: "travel", title: "Driver Waiting Out the Heat", subjectExample: "a jeep driver dozing with his hat over his face in the shade of the open door, midday desert glaring white beyond, one boot up on the dashboard", chipIDs: ["light.hardsun", "pose.candidtravel", "color.faded"], note: "A real in-between travel moment — the wait, not the destination. Harsh midday light is the honest choice here.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.travel.foggy-harbor-dawn", studio: "travel", title: "Fog Eating the Harbor", subjectExample: "a small fishing harbor at dawn half-swallowed by fog, one boat's mast and a gull emerging, the water flat pewter, a single working light glowing on a jetty", chipIDs: ["light.overcast", "env.foggymoor", "color.coldsteel"], note: "The fog hiding most of the scene is the point — mystery over grandeur, and the one jetty light gives it a pulse.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.travel.harmattan-plaza", studio: "travel", title: "Dust-Sun Over the Plaza", subjectExample: "an old man scattering feed to pigeons across a wide stone plaza, the low sun dimmed to a pale coin behind dust haze, his long shadow raking the flagstones", chipIDs: ["light.harmattan", "frame.wide", "color.warm"], note: "The dimmed coin-sun is the whole photo — the haze, not postcard blue, gives the sense of place. Yellow circle: keep the crowd sparse; dense distant figures blur and warp.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.travel.hostel-window-map", studio: "travel", title: "Planning by the Window", subjectExample: "a traveler's hands spreading a creased paper map on a sunlit hostel windowsill, coffee-ring stains on the paper, a bitten pastry and cheap sunglasses beside it", chipIDs: ["light.window", "pose.candidtravel", "env.wood"], note: "The lived-in clutter — coffee rings, the bitten pastry — makes it a real morning. Yellow circle: any text on the map will be gibberish; keep it soft and out of focus.", badge: .yellow, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 4),
        .init(id: "rcp.travel.nadir-saltpans", studio: "travel", title: "Salt Pans From Above", subjectExample: "a straight-down drone view of pink and white salt evaporation pans, a lone worker's cart carving a thin dark line across the geometric grid of color", chipIDs: ["angle.birdseye", "color.vibrant", "frame.centered"], note: "The tiny cart-track gives scale and turns a pattern into a place. Yellow circle: keep the human element a single small shape; figures don't hold up at this distance.", badge: .yellow, featured: false, tier: .klein9B, steps: 16, aspectW: 1, aspectH: 1),
        .init(id: "rcp.travel.tired-hiker-summit", studio: "travel", title: "Nothing Left at the Top", subjectExample: "a hiker slumped on a summit boulder, boots off and steam rising from wet socks, staring blankly at the view with the flat exhaustion of someone who's done", chipIDs: ["pose.candidtravel", "light.overcast", "color.muted"], note: "Exhaustion, not triumph — the steam off the wet socks is the true detail. Overcast flatness suits the mood.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.anime.90s-ova-arcade", studio: "anime", title: "80s OVA, Arcade Glow", subjectExample: "a delinquent girl in a leather jacket slamming an arcade cabinet that ate her coin, cigarette dangling, CRT glow lighting her scowl, VHS grain over everything", chipIDs: ["style.vhs80s", "light.practical", "color.faded"], note: "Retro OVA texture and a real flash of frustration. 🟡 Arcade marquee lettering will be gibberish; keep signage as colored glow, not readable brands.", badge: .yellow, featured: true, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 3),
        .init(id: "rcp.anime.chibi-boss-fight", studio: "anime", title: "Chibi Rage, Tiny Fists", subjectExample: "a furious chibi swordsman barely knee-high stomping and shaking two tiny fists at a house cat that has flopped indifferently across his quest scroll", chipIDs: ["style.chibi", "expr.laughing", "color.vibrant"], note: "Chibi proportions milked for a real tantrum gag. 🟡 Any text on the quest scroll will be fake script — leave it blank or crumpled.", badge: .green, featured: false, tier: .klein9B, steps: 14, aspectW: 1, aspectH: 1),
        .init(id: "rcp.anime.cyberpunk-ramen-cat", studio: "anime", title: "Neon Alley, Cat Steals the Fish", subjectExample: "a fat calico cat caught mid-sprint, body stretched low, a whole grilled fish clamped tightly in its jaws, tail streaming behind; an angry hunched noodle-cart cook lunging after it, arm raised high swinging a metal ladle, mouth open shouting, looking directly at the fleeing cat; rain-slick narrow neon alley, magenta and cyan signs reflecting on wet pavement; slight motion blur on the cat's legs, candid street photo, shallow depth of field, neon cyberpunk look, dense magenta-and-cyan glow, wet streets and hazy backlit atmosphere, in a narrow rainy alley lit by colorful neon reflections on wet pavement, moody neon lighting with colored reflections", chipIDs: [], note: "Cyberpunk saturation on a petty street-level crime. 🟡 Dense neon signage will read as fake glyphs — lean into unreadable glow rather than legible words.", badge: .yellow, featured: true, tier: .klein9B, steps: 4, quality: .best, aspectW: 3, aspectH: 2, seed: 2010171113434663046),
        .init(id: "rcp.anime.ghibli-kitchen", studio: "anime", title: "Ghibli Breakfast, Egg Overflowing", subjectExample: "a plump grandmother holding both halves of a single cracked brown eggshell close together above a pan, one stream of glossy translucent egg white with a bright orange yolk pouring down onto sizzling white rice, a thin trail of egg running down the outer side of the pan onto the stovetop, steam rising; warm morning light through a fern-crowded window behind her, cozy cluttered kitchen; soft focus background, as a soft watercolor anime illustration, gentle washes of color bleeding into clean ink lines, warm color grading with golden tones, soft window light from one side, gentle falloff into shadow", chipIDs: [], note: "The food-that-looks-alive register, but caught at the messy overflow moment. 🟡 Hands holding the egg may warp — favor the wider gesture over tight finger detail.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 3, aspectH: 2, seed: 12245476939970641226),
        .init(id: "rcp.anime.gouache-tram", studio: "anime", title: "Gouache Tram, Fogged Window", subjectExample: "a drowsy office worker in a white shirt sitting upright in a tram seat, his body vertical, head tipped to the side so that his temple leans against the vertical window glass beside him, eyes closed, mouth slightly open, hands resting in his lap; dark evening city outside, glowing streetlights and neon signs smeared into soft blurry blobs, deep blue dusk sky, painted in gouache, flat matte opaque color, visible brush strokes and soft poster-like shapes, muted, desaturated color palette, cool blue-hour twilight, soft ambient light", chipIDs: [], note: "Flat matte gouache and a mundane commute reframed as a small tender scene. 🟡 Reflections in the window can double the face oddly — keep the fog heavy to hide it.", badge: .green, featured: false, tier: .klein9B, steps: 8, quality: .standard, aspectW: 3, aspectH: 2, seed: 887822348965587456),
        .init(id: "rcp.anime.mangaink-onsen", studio: "anime", title: "Manga Ink: Onsen Standoff", subjectExample: "an old macaque and a young tourist woman both soaking in a steaming outdoor onsen pool, submerged up to their shoulders in the water, facing each other at close range in a staring contest; the macaque with narrowed eyes and a stern wrinkled frown, the woman with huge wide-open startled eyes and raised eyebrows, their faces level and inches apart, steam curling up between them; black-and-white manga ink art, crisp linework, screentone dot shading and hatching, high contrast, deep blacks, as black-and-white manga ink art, crisp linework with screentone dot shading and hatching, high-contrast black and white, deep blacks, bright highlights, a two-shot framing two subjects together in the same frame", chipIDs: [], note: "High-contrast manga ink on a deadpan animal-versus-human standoff. 🟡 Heavy screentone steam can flatten depth — keep clear black separation between the two subjects.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 3, aspectH: 2, seed: 8170511459463912748),
        .init(id: "rcp.anime.rooftop-noodles", studio: "anime", title: "Late-Night Rooftop Noodles", subjectExample: "a tired teenage girl in an oversized school cardigan sitting cross-legged on metal fire escape grating at night, both legs fully visible folded under her, holding a cup of instant noodles in one hand and chopsticks in the other, slurping noodles, thick steam rising from the cup fogging up her round glasses with white haze, one white sock slipping down her ankle; dark brick wall and metal railing of the fire escape, city windows glowing far below; 1990s hand-painted anime cel, slightly grainy retro color, soft film bloom, cool night cast with warm halated glow around lights, a warm pool of light close to the subject fading into ambient dark, in the style of a 1990s hand-painted anime cel, slightly grainy retro color and soft film bloom, shot on CineStill 800T tungsten film at night, cool cast with warm halated glow around lights, lit by a visible practical lamp in the scene, a warm pool of light close to the subject fading into ambient dark", chipIDs: [], note: "Commits to a real quiet-hour mood over a hero pose. 🟡 Klein renders any noodle-cup label as fake squiggles; keep packaging text out of frame.", badge: .green, featured: true, tier: .klein9B, steps: 4, quality: .standard, aspectW: 4, aspectH: 5, seed: 379275862202978002),
        .init(id: "rcp.anime.shinkai-crossing", studio: "anime", title: "Shinkai Sky, Empty Crossing", subjectExample: "a lone student pausing mid-stride at a wide suburban level crossing, red barrier lights blinking, an impossible cathedral of cumulus stacked above", chipIDs: ["style.anime", "light.golden", "lens.anamorphic"], note: "Makoto Shinkai's whole thing is the sky dwarfing a small human moment. 🟡 Fine background detail (train wires, distant signage) can smear — keep the human small and the sky the star.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.anime.shonen-eyecatch", studio: "anime", title: "Shonen: Mid-Air, Out of Stamina", subjectExample: "a spiky-haired fighter leaping in for a finishing blow but his stomach loudly growls, a sweatdrop and a comic vein popping, speed lines still blazing behind him", chipIDs: ["style.shonen", "pose.midleap", "color.vibrant"], note: "Shonen action pomp punctured by a gag beat. 🟡 Effect lines and a busy background can crowd the figure — keep the pose reading clearly as the anchor.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9),
        .init(id: "rcp.anime.webtoon-gym", studio: "anime", title: "Webtoon: Dropped the Dumbbell", subjectExample: "a lanky guy in a gym clutching his right foot with both hands, hopping on his left leg, face scrunched in exaggerated pain, mouth open in a yell, one big comic tear flying off his cheek, a heavy dumbbell lying on the floor right beside his foot where it just landed; a girl sitting on the next bench laughing hard, big open smile, one hand covering her mouth, pointing at him with the other hand; webtoon style, clean outlines, bright flat digital coloring, soft cell shadows, modern training gym with rubber flooring and equipment racks, soft even diffused light, in a webtoon style, clean outlines and bright flat digital coloring with soft cell shadows, inside a modern training gym, rubber flooring and racks of equipment under even overhead light, soft, even, diffused light, gentle wraparound shading with no harsh shadows", chipIDs: [], note: "Clean flat webtoon coloring on a small humiliating slapstick beat. 🟡 The onlooker's half-suppressed grin is the point — vary her expression from the hero's pain.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 4, aspectH: 5, seed: 3419747046987743250),
        .init(id: "rcp.cartoon3d.aardman-thumbprint", studio: "cartoon3d", title: "Aardman clay character, sheepish", subjectExample: "a stout Plasticine sheep farmer in a knitted vest, one eyebrow cocked in a sheepish half-grin, visible thumbprints pressed into the clay of his cheeks", chipIDs: ["style.claymation", "frame.half", "light.window"], note: "Handmade tactile look; the thumbprints and knitted-vest texture are the whole point. Keep the modelling-clay surface soft and matte.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.cartoon3d.anime90s-vending", studio: "cartoon3d", title: "90s anime cel, 2am coffee", subjectExample: "a tired office worker in a loosened tie buying coffee from a glowing vending machine on an empty street at 2am, 1990s hand-painted anime cel with soft film bloom", chipIDs: ["style.anime90s", "light.practical", "env.rainyneonalley"], note: "The mundane 2am vending-machine beat and retro cel grain give a specific melancholy mood, not a battle-anime default.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9),
        .init(id: "rcp.cartoon3d.celshade-noodle-slurp", studio: "cartoon3d", title: "Flat cel cartoon, noodle slurp", subjectExample: "a chubby cat in a tiny apron holding a bowl of ramen with both paws, one long noodle rising from the bowl in a single smooth arc through the air and ending in the cat's mouth, cheeks puffed mid-slurp, happy closed eyes; flat vector-style illustration, two-tone cel shading, heavy black outline, bold solid fills, crisp edges, vibrant saturated colors, plain white background", chipIDs: [], note: "Commit hard to clean toon shading; the absurd looping noodle is the joke, not a straight gag pose. Hard shadow edges keep it authored.", badge: .green, featured: true, tier: .klein9B, steps: 6, quality: .standard, aspectW: 4, aspectH: 5, seed: 1761179616126674062),
        .init(id: "rcp.cartoon3d.chibi-defiant-broccoli", studio: "cartoon3d", title: "Chibi kid vs. broccoli", subjectExample: "a tiny chibi toddler in a highchair, cheeks puffed and arms crossed in total defiance, one lonely broccoli floret sitting on the tray, cute chibi style", chipIDs: ["style.chibi", "pose.armscrossed", "color.pastel"], note: "Humor from a real standoff; the defiant puffed cheeks and one dreaded floret, not a straight cute face. Oversized head, tiny body.", badge: .green, featured: false, tier: .klein9B, steps: 14, aspectW: 1, aspectH: 1),
        .init(id: "rcp.cartoon3d.claytoy-product-chip", studio: "cartoon3d", title: "Clay-render toy, on the shelf", subjectExample: "a chunky stylized 3D toy robot with a chipped painted eye and scuffed knees, standing among wooden blocks on a sunlit kid's shelf, polished render look, polished 3D render look, smooth shaded surfaces, soft even bounced light filling the shadows and clean glossy reflections, in a playful kids room with soft toys, bright furniture and gentle daylight, soft window light from one side, gentle falloff into shadow", chipIDs: [], note: "Product-desirability rules apply; the chipped eye and scuffed knees make it read as a loved, played-with toy, not a floating catalog cutout.", badge: .green, featured: false, tier: .klein9B, steps: 10, quality: .standard, aspectW: 4, aspectH: 3, seed: 12270161734994479882),
        .init(id: "rcp.cartoon3d.cutpaper-fox-moon", studio: "cartoon3d", title: "Cut-paper collage, fox at night", subjectExample: "a small paper fox on a hilltop of torn-edge grass peering up at an enormous layered paper moon, cut-paper collage with soft drop shadows", chipIDs: ["style.cutpaper", "frame.negspace", "light.blue"], note: "Layered torn-paper depth and vast negative space give a crafted picture-book stillness, a moment of wonder rather than a busy scene.", badge: .green, featured: false, tier: .klein9B, steps: 14, aspectW: 2, aspectH: 3),
        .init(id: "rcp.cartoon3d.laika-miniature-tilt", studio: "cartoon3d", title: "Laika stop-motion miniature", subjectExample: "a tiny felt-and-wire witch stirring a cauldron in a mossy handmade forest set, shot on a long lens with a narrow band of focus, Laika stop-motion miniature", chipIDs: ["style.tiltshift", "lens.tele135", "light.dappled"], note: "The tilt-shift miniature tell plus visible felt-and-wire construction reads as a real handmade set, not CG; very shallow focus sells the scale.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.cartoon3d.pixar-freckles-gap", studio: "cartoon3d", title: "Pixar-style close-up, mid-laugh", subjectExample: "a freckled 8-year-old boy laughing with his head tilted back, eyes squeezed shut, wide open mouth, his two upper front teeth clearly absent leaving one large dark empty gap in the middle of his smile, remaining teeth small and white; Pixar-style 3D character, soft bounced fill light, low contrast natural shading, close-up shot", chipIDs: [], note: "Eyes squeezed shut and the wobbly tooth sell a caught moment over a posed appealing render; warm bounced light and subsurface skin do the rest.", badge: .green, featured: true, tier: .klein9B, steps: 6, quality: .standard, aspectW: 4, aspectH: 5, seed: 4048905308088044904),
        .init(id: "rcp.cartoon3d.pixar-grandpa-nap", studio: "cartoon3d", title: "Pixar elder, mid-snore", subjectExample: "a round-nosed old man asleep in a recliner mid-snore, glasses askew and a crossword sliding off his lap, cat curled on his belly, Pixar-style 3D with warm subsurface skin", chipIDs: ["frame.half", "light.practical", "color.warm"], note: "Appealing exaggerated proportions plus the caught mid-snore beat (glasses askew, crossword sliding) make a real moment with genuine warmth.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.cartoon3d.spiderverse-rain-halftone", studio: "cartoon3d", title: "Spider-Verse frame, rain-soaked", subjectExample: "a teenage skater in a hood frozen mid-ollie over a puddle, droplets suspended in the air, drawn as a Spider-Verse comic frame with Ben-Day halftone and print misregistration", chipIDs: ["style.graphicnovel", "pose.midaction", "color.vibrant"], note: "🟡 Bold inks and misregistration read as authored comic art; any onomatopoeia or sign lettering renders garbled, so keep text out of the plan.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.food.burntedge", studio: "food", title: "The Burnt Corner Nobody Minds", subjectExample: "a slice of homemade lasagna resting on a plate, one charred cheese edge dark and blistered, molten layers sagging with a slow cheese pull, set on a well-worn home kitchen counter", chipIDs: ["light.practical", "env.kitchen", "color.warm"], note: "The over-browned corner reads homemade, not test-kitchen sterile. 🟡 Cheese-pull and drip look great; plated keeps the geometry solved.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 3),
        .init(id: "rcp.food.dumplingsteam", studio: "food", title: "Bamboo Lid, Just Lifted", subjectExample: "a bamboo steamer lid tilted up, a burst of steam fogging the shot, soup dumplings glistening below, condensation on a metal cart in a busy dim sum hall", chipIDs: ["style.documentary", "light.window", "color.cinestill50d"], note: "The reveal moment, steam and all, over a clean overhead flat-lay. 🟡 Heavy steam can wash detail — keep one dumpling sharp as the anchor.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 4),
        .init(id: "rcp.food.gincondense", studio: "food", title: "Condensation, Fingerprinted", subjectExample: "a gin and tonic sweating hard in summer heat, a single clean finger-drag swiped straight down through the frost on the front of the glass, one lime wheel notched onto the rim and tilted askew, blurred garden light behind", chipIDs: ["light.golden", "color.pro400h", "lens.85mm"], note: "The smudge makes it real and wanted, not a catalog cutout. 🟡 Bubbles and beaded condensation render beautifully — let the background go soft, and keep the lime a single wheel on the rim.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5),
        .init(id: "rcp.food.honeypull", studio: "food", title: "Honey Caught Mid-Drip", subjectExample: "a wooden dipper lifted from a jar, one unbroken thread of honey stretching down and catching the light, a torn heel of bread waiting below on a linen napkin", chipIDs: ["light.rim", "color.warm", "lens.macro100"], note: "The suspended drip is the whole shot — timing over arrangement. 🟡 Backlight makes honey glow; freeze the thread so it stays a clean single strand.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5),
        .init(id: "rcp.food.marketdawn", studio: "food", title: "Tomatoes Before the Crowd", subjectExample: "a crate of imperfect heirloom tomatoes at a farmers market stall at 6am, one split from ripeness, dew on the skins, a vendor's shadow falling across in low sun", chipIDs: ["light.golden", "style.documentary", "env.wood"], note: "A sense of place and hour, not a supermarket-perfect pyramid. 🟡 Irregular produce is a strength here — embrace the odd shapes and splits.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.food.oystershuck", studio: "food", title: "Brine Still on the Knife", subjectExample: "a just-shucked oyster on crushed ice, a short stubby oyster shucking knife laid flat beside it still beaded with brine, a squeezed lemon half on a smooth clean wooden board", chipIDs: ["light.lowkey", "env.slatesurface", "lens.macro100"], note: "Freshness read through the tools, not a symmetrical seafood tower. 🟡 Fine ice and shell texture are where Klein shines — lean into the macro detail, and keep the board surface smooth.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.food.ramensweat", studio: "food", title: "Ramen Fog on the Glasses", subjectExample: "a bowl of tonkotsu ramen just set down, so hot the steam has fogged the eyeglasses of the diner leaning in over it, one hand lifting noodles with a single pair of chopsticks resting naturally, a cramped counter shop with plain unmarked walls behind", chipIDs: ["style.documentary", "light.practical", "color.cinestill800t"], note: "A funny, true small moment — the fogged glasses, not a top-down bowl. 🟡 Keep the diner's face partial and soft and give him ONE pair of chopsticks in one hand; Klein handles a single leaning silhouette and one solved grip better than two hands near the face.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 2),
        .init(id: "rcp.food.teamugquiet", studio: "food", title: "Tea Gone Cold by the Window", subjectExample: "a half-drunk mug of dark reddish-brown tea gone cold on a rainy windowsill, its surface perfectly flat and still under a thin cooled skin, a used teabag string draped over the plain ceramic rim, condensation and blurred grey rain on the window behind", chipIDs: ["light.overcast", "env.kitchen", "color.softmatte"], note: "A quiet, melancholy still-life — the abandoned cup, not a fresh steaming pour. 🟡 Soft flat light and the rain-streaked glass carry the whole mood.", badge: .green, featured: false, tier: .klein9B, steps: 14, aspectW: 4, aspectH: 5),
        .init(id: "rcp.food.torncrumb", studio: "food", title: "Torn Focaccia, Just Broken", subjectExample: "a torn wedge of rosemary focaccia resting on parchment with steam still rising from the ragged crumb, one hand at the edge of frame having just pulled it apart, fingers relaxed and clearly separated, olive oil glossing the torn edge, flour dusted on the knuckles", chipIDs: ["light.window", "color.portra", "angle.threequarter"], note: "The just-torn moment beats any pristine loaf. 🟡 Klein renders hands loosely — one relaxed hand at the frame edge keeps finger-count from reading wrong.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 5),
        .init(id: "rcp.macro.chocolate-crack", studio: "macro", title: "Chocolate, Snapped in Half", subjectExample: "A square of dark chocolate snapped a heartbeat ago, the fracture face still sharp and matte, a faint bloom of cocoa dust puffing off the break, one fingertip steadying the far edge, warm side light", chipIDs: ["lens.macro100", "light.singlesoft", "color.warm"], note: "🟡 A single fingertip is fine, but keep full hands out of frame — Klein still fumbles finger counts and joints. Swap for a snapped biscotti, a broken wafer, or a cracked toffee slab.", badge: .yellow, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.macro.emerald-inclusions", studio: "macro", title: "Emerald, Its Own Garden", subjectExample: "A raw emerald lit hard from behind so its internal fissures and jardin inclusions glow like a tiny green landscape, one corner left rough and uncut, a crisp rim light along the top edge", chipIDs: ["lens.macro", "light.hazeback", "color.crushedblacks"], note: "Real emeralds are flawed; the rough uncut corner and inclusions are the point, not a defect to hide. Swap for raw amber, an opal, or a chunk of turquoise.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 1, aspectH: 1),
        .init(id: "rcp.macro.espresso-crema", studio: "macro", title: "Espresso Crema, Fresh Pull", subjectExample: "The surface of a just-pulled shot of black espresso in extreme macro, a thin hazelnut-brown tiger-striped crema swirling over the dark coffee beneath, one tiny bubble caught mid-pop at the rim, faint steam rising in low warm light", chipIDs: ["lens.macro100", "light.singlesoft"], note: "The popping bubble and live swirl mark it as fresh, not staged. Swap for a flat-white rosetta, matcha foam, or beer head.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.macro.honey-drip", studio: "macro", title: "Honey, Mid-Drip on a Spoon", subjectExample: "A wooden honey dipper lifted from the jar, one unbroken amber thread stretching down and sagging off-center as it starts to break, a slow bubble rising inside the pooled honey below, warm kitchen window light", chipIDs: ["lens.macro100", "light.window", "color.warm"], note: "The sagging, off-center thread reads as a real caught pour, not a symmetrical render. Swap honey for maple syrup, caramel, or olive oil.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.macro.ink-tendril", studio: "macro", title: "Ink Bloom, Frozen", subjectExample: "A single thread of deep magenta ink unfurling into a jellyfish tendril in still water, backlit against pure black, one stray droplet peeling off the main bloom, caught high-speed", chipIDs: ["lens.freezeaction", "light.rim", "color.crushedblacks"], note: "Every bloom is unique; the one breaking-off droplet is the caught-moment detail. Swap the magenta for indigo, blood-red, or gold.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.macro.oil-water-cells", studio: "macro", title: "Oil and Water, Caught Merging", subjectExample: "Droplets of oil floating on water shot straight down, each dome acting as a lens over a blurred field of magenta and teal bokeh below, two droplets caught lopsided just as they merge into one", chipIDs: ["angle.birdseye", "env.bokehlights", "color.vibrant"], note: "The two droplets caught mid-merge give it a real moment instead of a tidy pattern. Swap the bokeh field below for warm sunset tones or cool blues.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 1, aspectH: 1),
        .init(id: "rcp.macro.pearl-strand", studio: "macro", title: "Pearl Strand, Loosely Coiled", subjectExample: "A strand of freshwater pearls coiled loosely on raw silk, soft window light catching each pearl's own imperfect nacre swirl, one pearl left slightly off-round, the silk knots visible between them", chipIDs: ["lens.macro100", "light.window", "env.linenbackdrop"], note: "Off-round pearls and visible knotting read as a real strand, not a synthetic render. Swap for jade beads, worry beads, or a coral necklace.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.macro.perfume-caustics", studio: "macro", title: "Perfume Bottle, Backlit on Wet Slate", subjectExample: "A faceted clear perfume bottle backlit hard, throwing a tangle of amber caustic light across wet dark slate, one drip running down the glass and a faint thumbprint smudge on the cap", chipIDs: ["light.hazeback", "env.slatesurface", "color.warm"], note: "🟡 Any label lettering renders as convincing gibberish — keep labels turned away or out of focus. Swap for a whisky bottle, olive oil cruet, or apothecary jar.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 4),
        .init(id: "rcp.macro.rust-patina", studio: "macro", title: "Rust, Close Enough to Touch", subjectExample: "The corner of a weathered steel plate where orange rust bleeds into flaking blue paint, one bright droplet of morning dew sitting in a corrosion pit, raking low sunlight across the crumbling texture", chipIDs: ["lens.macro100", "light.hardsun", "env.concretesurface"], note: "A single dew droplet gives scale and life to the decay. Swap the steel for weathered copper, an old padlock, or peeling boat hull.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.macro.thumbprint-ring", studio: "macro", title: "Ring, Just Off the Finger", subjectExample: "A worn platinum wedding band resting on a smooth slab of aged leather, just slid off and set down, one faint clouded smudge fogging the polished shank, years of tiny scratches on the metal catching a single hard spot light", chipIDs: ["lens.macro100", "light.chiaroscuro", "color.crushedblacks"], note: "The smudge and micro-scratches sell it as a real, worn object just set down rather than a catalog cutout. Swap for a signet ring, a pocket watch, or a heirloom locket. 🟡 Kept off the finger — a ring encircling a digit at macro scale renders as fused metal-and-skin.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 5),
        .init(id: "rcp.blackwhite.ballerina-taping-toes", studio: "blackwhite", title: "Backstage, taping toes", subjectExample: "A ballerina hunched on a dressing-room floor, her relaxed natural hands carefully winding tape around one raw blistered foot, tights laddered at one knee, a harsh bare bulb overhead, the crushed tutu tossed beside her", chipIDs: ["light.toplight", "style.documentary", "frame.half"], note: "The unglamorous backstage reality, blisters and all, is the real story. 🟡 Klein can soften tape and finger detail; keep the hands and feet a touch soft.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 5),
        .init(id: "rcp.blackwhite.child-mud-triumph", studio: "blackwhite", title: "Muddiest kid at the party", subjectExample: "A small kid at a garden party, filthy and triumphant in a ruined white outfit, both fists raised, having clearly just fallen in the flowerbed, scandalised adults' blurred legs behind", chipIDs: ["expr.laughing", "light.hardsun", "angle.low"], note: "A funny real situation shot from the kid's low proud angle. 🟡 Klein can distort the small child's face and the blurred adults; keep them soft.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.blackwhite.diver-toe-off-board", studio: "blackwhite", title: "The half-second before", subjectExample: "A small lone diver coiled in a low crouch at the very end of the high board, weight compressed and still, caught in the tense readable moment a breath before the spring, a plain unmarked swimsuit, the whole figure in one clear silhouette against the pool tiles far below", chipIDs: ["angle.low", "lens.freezeaction", "color.crushedblacks"], note: "The un-heroic instant before the perfect shape is the interesting one. 🟡 Klein bends mid-air limbs badly, so this is the coiled crouch just before the spring — a small, clear, single-silhouette figure.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 9, aspectH: 16),
        .init(id: "rcp.blackwhite.empty-pool-skater", studio: "blackwhite", title: "Bottom of the drained pool", subjectExample: "A skater resting at the bottom of a drained kidney-shaped pool, skateboard lying flat on the concrete beside him, one hand resting easy on the deck, looking up at the lip against a blown-out sky, cracked concrete curving up around him with faded unmarked spray-paint in soft abstract shapes", chipIDs: ["angle.low", "light.hardsun", "frame.wide"], note: "A specific real place with its history in the cracks and weathered paint, shot as a quiet pause not an action cliche.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.blackwhite.espresso-crema-thumbprint", studio: "blackwhite", title: "Espresso, someone's thumbprint", subjectExample: "A single espresso in a thick chipped ceramic cup, crema still settling, a barista's floury thumbprint smudged on the saucer, morning window light hitting the steam", chipIDs: ["light.window", "lens.macro100", "color.bw"], note: "The thumbprint and the chip make it a real wanted object, not a floating catalog cutout. Desire lives in the steam and the flaw.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.blackwhite.fogged-butcher-window", studio: "blackwhite", title: "Butcher, 6am", subjectExample: "A butcher seen through his own fogged shop window before opening, one relaxed natural hand drawing a knife across a honing steel, breath and cold glass turning him into a soft grey shape with only that working hand sharp where he wiped a clear patch", chipIDs: ["style.filmnoir", "light.window", "frame.half"], note: "Shooting through the fogged glass is the whole idea; the wiped patch is the only sharp thing. 🟡 Klein may not hold the crisp-to-soft boundary precisely and can soften hand detail.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 2),
        .init(id: "rcp.blackwhite.foundry-pour-sparks", studio: "blackwhite", title: "The pour", subjectExample: "A foundry worker mid-pour, tipping a crucible so a bright ribbon of glowing molten metal streams out and throws sparks that arc pure white across the frame, both hands steady on the crucible handle, his face lit orange-to-white from below through the heat shimmer, everything else swallowed in black", chipIDs: ["light.hardsingle", "color.crushedblacks", "frame.half"], note: "Real motivated light from the molten metal itself; the sparks carry the tonal range. 🟡 Klein can smear dense spark showers into mush and merge fingers on the grip.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 16, aspectH: 9),
        .init(id: "rcp.blackwhite.grandpa-cards-laugh", studio: "blackwhite", title: "Beaten at cards", subjectExample: "An old man throwing his head back laughing after losing a hand of cards to his granddaughter, a loose spread of face-down playing cards and a chipped teacup on the table, kitchen window light raking his crumpled face", chipIDs: ["expr.laughing", "light.window", "style.documentary"], note: "A genuine belly-laugh reacting to a real situation, not a sentimental posed family shot. 🟡 Keep the small girl's face soft or turned away.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.blackwhite.whiskey-melting-ice", studio: "blackwhite", title: "Whiskey, ice going", subjectExample: "A heavy tumbler of whiskey holding a single large ice cube resting against the glass, a bead of condensation running down onto worn bar wood, a burned ring from a hundred earlier glasses beside it", chipIDs: ["light.practical", "lens.macro100", "color.crushedblacks"], note: "The old burn-ring and the running drip make it a real used bar, not a slick product cutout.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 3),
        .init(id: "rcp.myth.avalanche-turn", studio: "myth", title: "The Slope Comes Alive", subjectExample: "a lone skier stopped at the edge of a vast open alpine bowl, a small dark silhouette, watching a real powder avalanche billow down a far slope clear across the valley, a towering backlit cloud of wind-driven snow spilling off the distant ridge under a cold blue sky", chipIDs: ["pose.midaction", "env.snowypeaks", "light.alpenglow", "frame.establishing"], note: "A real powder avalanche and the tiny skier against the mountain carry all the dread now — pure scale, no monster. 🟢 Keep the figure mid-ground in clear silhouette so the glance-back reads; let the backlit snow-cloud billow big behind them.", badge: .green, featured: false, tier: .klein9B, steps: 20, aspectW: 16, aspectH: 9),
        .init(id: "rcp.myth.diver-descent", studio: "myth", title: "The Descent Light", subjectExample: "a lone free-diver in a dark wetsuit descending headfirst along a single vertical guide rope into open ocean, arms streamlined against her sides in one clean silhouette, the water fading from bright turquoise near the surface down into deep abyssal blue below her, a single shaft of surface sunlight cutting down past her", chipIDs: ["light.godrays", "light.hazeback", "color.coldsteel", "style.silhouettefirst"], note: "The dread lives in the water itself — bright turquoise up top fading to abyssal black below, one shaft of light, one small diver. 🟢 Let the deep-blue gradient do the hiding; the emptiness and the single beam carry the awe, no shape needed.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 9, aspectH: 16),
        .init(id: "rcp.myth.drowned-street", studio: "myth", title: "The Drowned Village", subjectExample: "A lone woman stands waist-deep in the still floodwater of a drowned village lane at dusk, seen from the chest up, one hand resting flat on the glassy surface; a low bank of pale river-fog drifts down the lane behind her, and half-sunk doorways glow faint amber, their warm light mirrored in the motionless water.", chipIDs: ["light.practical", "color.faded", "frame.establishing"], note: "Real photographable scene now: still flooded lane at dusk, low river-fog and warm half-sunk doorways mirrored in motionless water. The dread comes from fog, solitude and the drowned village, not from any impossible current. Practical amber lamps anchor the reflection.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 5),
        .init(id: "rcp.myth.dust-plow", studio: "myth", title: "When the Haboob Comes", subjectExample: "a lone farmer standing still in dark backlit silhouette on cracked dry farmland, watching a real rolling haboob dust storm advance across the plain, a towering churning brown-orange wall of wind-driven dust filling the far horizon under a low sun, his hands resting quietly at his sides, one calm clear standing outline dwarfed by the approaching weather", chipIDs: ["env.sanddunes", "color.sepia", "light.dustplume", "style.silhouettefirst", "frame.establishing"], note: "1930s Dust-Bowl dread from a real haboob — the churning dust wall is genuine weather Klein renders cleanly, and the lone backlit silhouette carries the solitude. 🟢 Figure kept small, still and in silhouette so anatomy stays safe; the drama is all light and approaching storm.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.myth.frozen-lake-eye", studio: "myth", title: "Under the Black Ice", subjectExample: "a lone skater standing on vast black wild ice, viewed from directly overhead, her head bowed looking straight down at the ice under her skates, only the top of her head and shoulders visible from above; small white frozen methane bubbles stacked in columns descending deep below the surface, fading darker with depth, giving the ice a three-dimensional depth, thin pale cracks crossing the surface; cold steel-blue grade, desaturated cool tones, dappled light", chipIDs: [], note: "Shooting straight down through the ice is still the fresh angle — the viewer finds it the same instant she does. The real wonder now: Lake Baikal-style black ice actually freezes ribbons of white methane bubbles and pale cracks deep in the clear sheet, so the awe is genuinely down there, not implied. 🟢 Feet slightly apart, hands at her sides so the two skates read distinctly from the high angle; rendered at 20 steps.", badge: .green, featured: true, tier: .klein9B, steps: 6, quality: .standard, aspectW: 4, aspectH: 5, seed: 9090899362342214459),
        .init(id: "rcp.myth.ice-whiteout", studio: "myth", title: "The Whiteout Wall", subjectExample: "a lone climber in a red shell pressed flat against a towering blue-ice wall in a screaming alpine whiteout, one gloved hand steady on the ice-axe head as driving spindrift streams sideways across the frozen face, the tiny figure dwarfed by the vast pale wall of storm and ice rising into blank white above", chipIDs: ["env.snowypeaks", "color.coldsteel", "frame.establishing"], note: "The dread now lives entirely in the storm and the scale — a single human speck against a wall of driving snow and blue ice, no monster needed. 🟡 The whiteout naturally swallows hand and gear detail, so let the spindrift blur the axe grip; rendered at 20 steps for cleaner form where the glove does show.", badge: .green, featured: false, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 4),
        .init(id: "rcp.myth.lantern-forest", studio: "myth", title: "The Fog Takes the Trees", subjectExample: "a lone traveler in a long dark coat standing at the edge of a pine forest, full figure visible from head to boots, seen from behind at three-quarter angle, carrying an old lantern in one lowered hand, its warm firelight blooming into thick ground fog that swallows the far trunks; duotone grade of deep indigo shadows and warm cream highlights, misty pine forest, shafts of soft light between the trunks, warm flickering firelight, soft glow on the near side fading into deep amber shadow, duotone grade mapping the whole image into deep indigo shadows and warm cream highlights, in a misty pine forest with shafts of soft light between the trunks, warm flickering candle and firelight, soft glow on the near side fading into deep amber shadow", chipIDs: [], note: "No monster, no bent trees — a real rolling fog bank swallowing the far trunks does all the dread, the lantern glow blooming into the mist. 🟡 Keep the near trunks sharp so the forest stays legible before it dissolves into fog. One hand carries the lantern by its bail — a solved grip — at 20 steps for clean fingers.", badge: .green, featured: true, tier: .klein9B, steps: 4, quality: .standard, aspectW: 3, aspectH: 2, seed: 17781554839862684527),
        .init(id: "rcp.myth.marsh-lantern-eyes", studio: "myth", title: "Moonlit Marsh", subjectExample: "a woman poling a punt across a still black marsh on a windless night, both hands resting steady on the long wooden pole, a single warm lantern hung on the bow beside her, low silver ground-fog lying in sheets over the reeds while a full moon and its reflection glow on the mirror-flat water all around her, day-for-night grade, deep moonlit blue cast with crushed shadows and dim cool highlights, on a windswept foggy moor with muted desaturated tones, lit by a visible practical lamp in the scene, a warm pool of light close to the subject fading into ambient dark", chipIDs: [], note: "Real low ground-fog and a full moon over still water carry the marsh dread — no hovering lights, no implied creature, nothing the model must infer. Both hands rest on the pole and the lantern hangs on the bow so the grip stays one solved shape; render at 20 steps for clean hands and face. 🟢 Keep the fog low and even over the reeds; the lantern is the only warm light against the moonlit blue.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 16, aspectH: 9, seed: 1397146290886282115),
        .init(id: "rcp.myth.net-turns", studio: "myth", title: "The Sea Comes Over the Rail", subjectExample: "a crew of oilskin-clad fishermen braced shoulder to shoulder along the rail of a heaving deck, all hauling one thick heavy rope that runs down over the rail into the sea, a bulging fishing net full of fish just breaking the surface at the end of the rope, their bodies leaning back hard against the strain, boots planted wide on the wet deck; a towering grey storm swell rearing up behind them, wind-torn spray blasting sideways under a low iron sky; cold steel-blue grade, desaturated cool tones, clean neutral highlights, strong backlight through atmospheric haze, glowing rim light, wide establishing shot, cold steel-blue grade, desaturated cool tones with clean neutral highlights, strong backlight cutting through atmospheric haze, glowing rim on the subject and soft volumetric light beams, a wide establishing shot, the subject set deep within a sweeping environment", chipIDs: [], note: "Real North Atlantic storm does the mythic work now — the braced crew and the single taut rope sell the fight, the towering swell and sideways spray sell the danger, no creature required. 🟡 multiple hands on one rope can still soften; keep the group loose and mid-frame in clear separated silhouettes, rendered at 20 steps.", badge: .yellow, featured: true, tier: .klein9B, steps: 4, quality: .standard, aspectW: 3, aspectH: 2, seed: 953627453058940185),
        .init(id: "rcp.myth.old-woman-tide", studio: "myth", title: "She Waits for the Tide", subjectExample: "an old woman in yellow oilskins standing calm and still on wet ribbed tidal flats as a low bank of sea fog rolls in over heavy grey surf behind her, one gloved hand resting flat on her small dog's back pressed to her leg, the other hanging relaxed, a few gulls settled on the wet sand nearby", chipIDs: ["env.silkyseascape", "light.hazeback", "color.coldsteel"], note: "Her stillness against the fleeing gulls is the whole tension — everything runs but her, one hand steadying the dog. 🟡 The aged face and the flock can soften; gulls read best as pale motion streaks and the resting hand gives the model a solved shape.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 5),
        .init(id: "rcp.myth.rower-leviathan", studio: "myth", title: "The Rower and the Deep", subjectExample: "a lone fisherman in a small battered wooden dinghy far out on a heaving grey ocean, both weathered hands gripping the oars in one steady mid-pull, water sheeting off the blades, a towering dark storm swell rolling toward him as a great bank of sea-fog swallows the horizon behind, the tiny boat dwarfed by the vast churning sea, cold steel-blue grade, desaturated cool tones with clean neutral highlights, strong backlight cutting through atmospheric haze, glowing rim on the subject and soft volumetric light beams, a wide establishing shot, the subject set deep within a sweeping environment", chipIDs: [], note: "Real weather does the myth's work — a towering storm swell and a rolling wall of sea-fog dwarf the boat, no creature needed. Keep the man mid-ground with both hands on the oars so the pose reads clean; let the fog eat the horizon for scale and dread.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 2, aspectH: 3, seed: 3754448931244554372),
        .init(id: "rcp.myth.storm-shepherd-child", studio: "myth", title: "Hail on the Hillside", subjectExample: "a child standing beside a goat under a rock overhang, one hand holding a simple rope, both figures in clear separated silhouette as a green-black hailstorm swallows the valley, the first white stones scattered across the grass around their boots", chipIDs: ["light.dayfornight", "env.foggymoor", "color.coldsteel"], note: "The sickly green storm light does the mythic work without any creature at all. 🟡 Child and goat share the frame — kept them in clear separated silhouettes so limbs don't blend.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 4, aspectH: 5),
        .init(id: "rcp.myth.troll-bridge", studio: "myth", title: "Torch on the Bridge", subjectExample: "a lone figure standing planted at the center of an old stone bridge, one steady arm raising a single burning torch aloft, a thick wall of night river-fog rolling in and swallowing the far arches, a flood-swollen river roaring pale white beneath the stone, the torch the only warm light in the dark, high-contrast grade with deep crushed blacks and bright clean highlights, warm flickering candle and firelight, soft glow on the near side fading into deep amber shadow, strong backlight cutting through atmospheric haze, glowing rim on the subject and soft volumetric light beams", chipIDs: [], note: "The torch is your only light and the figure's only certainty — everything past the near arch dissolves into the fog. 🟡 Frame wide so the raised hand stays small; let the rolling mist, not a shape inside it, carry the dread.", badge: .green, featured: false, tier: .klein9B, steps: 4, quality: .standard, aspectW: 2, aspectH: 3, seed: 17090355123183385450),
        .init(id: "rcp.myth.wildfire-ridge", studio: "myth", title: "Running the Ridge", subjectExample: "a lone shepherd running along a bare ridgeline with their dog bounding just ahead, both in strong side-on silhouette, a wall of wildfire crowning the hills behind, embers streaming sideways in the wind, feet driving hard against the rock", chipIDs: ["pose.midaction", "light.hazeback", "color.warm"], note: "The sideways embers make the wind visible and give real motion. 🟡 The dog and figure read best in clear side-on silhouette; fine facial detail against that glare will wash out.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 16, aspectH: 9),
        .init(id: "rcp.cities.diner-window-rain", studio: "cities", title: "Diner Window, Raining", subjectExample: "seen from the wet street through a fogged diner window at night, a lone customer inside framed from the chest up, both hands wrapped calmly around a coffee mug resting on the counter, condensation and neon reflections blurring the glass", chipIDs: ["style.neonoir", "light.practical", "color.cinestill800t"], note: "Shooting through the fogged, rain-streaked glass is the one flaw that sells it as real and lonely. 🟡 the diner's neon reflections stay abstract in the fog, and the mug gives the hands a solved shape.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.cities.favela-kite", studio: "cities", title: "Kite Over the Favela", subjectExample: "a hillside favela cascading down in evening gold, tangled wires and hanging washing everywhere, one small paper kite up in the clear sky above the rooftops", chipIDs: ["light.golden", "angle.high", "color.warm"], note: "The single kite over the chaos of wires is the lift the frame needs — one kite, not a swarm. 🟡 the tangle of wires and washing may render mushy up close.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        .init(id: "rcp.cities.hilltop-terracotta", studio: "cities", title: "Terracotta at Sunset", subjectExample: "an aerial of a medieval hilltop village at sunset, terracotta roofs packed tight inside old stone walls, long shadows raking across the tiles", chipIDs: ["angle.aerial", "light.golden", "lens.tiltshift"], note: "The tilt-shift band makes the ancient town read almost like a model — an authored choice, not a drone-stock cliche.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 3),
        .init(id: "rcp.cities.izakaya-noren", studio: "cities", title: "Under the Noren", subjectExample: "a Japanese salaryman in a plain dark suit and no coat, walking through a narrow Tokyo alley at night, his right hand pulling one panel of a hanging fabric noren curtain aside as he passes a low doorway — the noren is a separate short cloth hanging from a horizontal rod above the door, clearly apart from his suit and not touching his clothes, steam rising from a nearby yakitori grill, red paper lanterns glowing along the rain-slicked alley", chipIDs: ["style.neonoir", "light.practical", "color.cinestill800t"], note: "The noren is a separate cloth on a rod above the doorway — kept explicitly apart from his suit so Klein doesn't fuse it into a worker's cloak or hand him a pole. Rendered at 20 steps for a clean hand on the curtain. 🟡 Japanese text on the signs and noren looks convincingly foreign but is not real language.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 2),
        .init(id: "rcp.cities.laundry-cat", studio: "cities", title: "The Cat and the Sunbeam", subjectExample: "a narrow old-town alley strung with dripping laundry lines overhead, a single cat crossing one hard shaft of afternoon sun, everything else in cool shadow", chipIDs: ["light.dappled", "color.faded", "lens.film35"], note: "Catch the cat exactly in the one sunbeam; the wet laundry and shadow do the rest. Shot on 35mm so it feels found, not staged.", badge: .green, featured: false, tier: .klein9B, steps: 15, aspectW: 4, aspectH: 5),
        .init(id: "rcp.cities.market-steam-vendor", studio: "cities", title: "Steam and a Grin", subjectExample: "a cramped night market stall wreathed in griddle steam, a street-food vendor caught mid-laugh, one hand resting flat on the counter beside a single wrapped paper bag, warm lamplight catching the vapor", chipIDs: ["light.practical", "expr.laughing", "color.warm"], note: "A real, genuine laugh over the counter — the human beat that stops it being a food-stock plate. 🟡 background market signage stays out of focus; the single resting hand keeps the fingers clean.", badge: .yellow, featured: false, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 2),
        .init(id: "rcp.cities.noon-dog", studio: "cities", title: "The Only Shade", subjectExample: "a dusty desert town's single sun-bleached main street at high noon, heat shimmer rippling off the road, one dog asleep on its side in the only strip of shade, legs stretched out", chipIDs: ["light.hardsun", "style.western", "color.bleachbypass"], note: "High noon is the unfashionable hour on purpose — the flat brutal light and the sleeping dog carry it. No people at all.", badge: .green, featured: false, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.cities.rooftop-laundry-boy", studio: "cities", title: "Rooftop Wash Day", subjectExample: "a densely packed old-city street at midday seen from a rooftop, lines of bright washing strung between buildings snapping in the wind; a boy standing safely on the rooftop behind a waist-high concrete parapet, leaning forward with both forearms resting flat on top of the ledge, chin slightly lowered, watching the street below, his whole upper body above the wall, seen from behind and slightly to the side; shot on Kodak Ektachrome slide film, clean punchy color, crisp blues, accurate skin tones, harsh direct sunlight, deep high-contrast shadows, shot on Kodak Ektachrome slide film, clean punchy color, crisp blues and accurate skin tones, harsh direct sunlight, deep high-contrast shadows, photographed from a high angle, looking down on the subject", chipIDs: [], note: "The kid is watching something we can't see — that offscreen attention gives the frame a pulse. Ektachrome keeps the washing punchy and real.", badge: .green, featured: false, tier: .klein9B, steps: 6, quality: .standard, aspectW: 4, aspectH: 5, seed: 14988638949163141177),
        .init(id: "rcp.cities.stairs-fruitseller", studio: "cities", title: "The Long Blue Staircase", subjectExample: "a steep painted-blue stairway climbing a Mediterranean hill town, an old fruit seller resting halfway up beside his crates, cats dozing on the warm steps around him", chipIDs: ["light.golden", "color.pro400h", "frame.wide"], note: "The seller resting, not selling, is the human truth — a pause, not a pose. Pro 400H gives it that soft, sun-faded travel-diary look.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 4, aspectH: 5),
        .init(id: "rcp.cities.subway-yellowline", studio: "cities", title: "Late on the Platform", subjectExample: "an empty late-night subway platform, white tile and green fluorescent light, a blank unmarked green station board on the wall, one figure standing far down at the far end right on the yellow line", chipIDs: ["env.subwayplatform", "angle.onepoint", "color.crushedblacks"], note: "The dead-symmetrical one-point tile receding to the lone distant figure is the tension. That flat fluorescent green is the truth of the place.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9),
        .init(id: "rcp.cities.tram-condensation", studio: "cities", title: "Last Tram Home", subjectExample: "a night tram sliding through wet city streets, a blank unlit destination panel above its windows, warm interior light spilling out, one tired passenger's face pressed near the fogged window, motion streaking past outside", chipIDs: ["lens.panblur", "light.practical", "color.cinestill800t"], note: "The panning blur streaks the street while the tired face stays sharp — exhaustion frozen in motion. 🟡 the destination panel is kept blank and unmarked so there is no fake text.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 16, aspectH: 9),
        .init(id: "rcp.cities.umbrella-river", studio: "cities", title: "River of Umbrellas", subjectExample: "a packed pedestrian crossing at night seen straight down from a high window, hundreds of black umbrellas mid-stream, one lone red one drifting against the flow, softly lit by plain unmarked storefronts below", chipIDs: ["angle.birdseye", "light.neon", "color.cinestill800t"], note: "The lone red umbrella going the wrong way is the whole shot — keep the crowd anonymous. 🟡 dense crowds and tiny faces will smear, which here reads as rain not error; storefronts kept plain so no garbled signage.", badge: .yellow, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 4),
        .init(id: "rcp.cities.woodsmoke-dawn", studio: "cities", title: "Woodsmoke at Dawn", subjectExample: "a stone village lane just after dawn, low woodsmoke hanging at knee height, a rusted bicycle leaning against a wall, every shutter still closed", chipIDs: ["light.golden", "env.mistpine", "color.softmatte"], note: "The held-low woodsmoke and the closed shutters say nobody is awake yet — that stillness is the subject.", badge: .green, featured: false, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 2),
        // === IDEA-inspired presets (2026-07-04, civitai-referenced, concept-critic hardened; seeds unpinned — user renders) ===
        .init(id: "rcp.brand.chrome-film-shrouded-figure", studio: "brand", title: "Silver Shroud", subjectExample: "a tall fashion figure against a deep near-black studio, its head a smooth featureless polished mirror-black form with no face, draped from crown to floor in one large separate sheet of crinkled translucent silver film held loosely apart from the glossy black body beneath, one bare human hand resting flat and calm against the film at waist height, a single hard side light carving bright specular highlights along the crumpled sheen", chipIDs: ["env.darkseamless", "color.steelcool", "light.perfumedrama"], note: "🟡 The mirror-black head is stated featureless so Klein has no face to mangle behind the film, and the sheet is named a separate drape apart from the body; the one visible bare hand is the only wobble, so it rests flat at 20 steps to keep it clean.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 2, aspectH: 3),
        .init(id: "rcp.gameconcept.emberlight-warrior-mage", studio: "gameconcept", title: "Emberlight Vanguard", subjectExample: "a lone young warrior in ornately engraved plate armor and a long dark flowing cape, standing tall on a smoky battlefield, one bare open palm turned upward with a single glowing sphere of fire hovering a hand's width above the palm as a separate floating object not touching the skin, the other arm resting straight at his side, swept-back pale hair caught by the wind and backlit by the blaze, a few faceless full-helmeted soldiers as low dark silhouettes at a distance around his feet", chipIDs: ["style.painterlyconcept", "light.hazeback", "angle.hero", "color.amberblack"], note: "🟡 The fire sphere is a separate object floating a hand's width ABOVE one open upturned palm (not touching it), the other arm hangs solved at the side, and soldiers stay faceless full-helmeted silhouettes at distance so no crowd-face smear. 20 steps for the lit face and single visible hand.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 2, aspectH: 3),
        .init(id: "rcp.macro.impasto-navy-amber-ridges", studio: "macro", title: "Molten Ridgelines", subjectExample: "an extreme macro close-up of thick oil paint troweled into wavy diagonal ridges filling the whole frame, deep navy and slate-blue peaks with amber and burnt-orange glowing along the crests, every palette-knife furrow and dried impasto ripple standing in tactile relief, low grazing light raking across the crusted brushwork, no object, edge, figure, or text anywhere in frame", chipIDs: ["env.materialmacro", "light.grazetexture", "color.tealorange", "lens.macro100"], note: "🟢 A pure impasto paint-texture field with grazing rake light — no subject, hands, or text for Klein to literalize; the palette-knife/furrow wording keeps it reading as dried oil paint rather than water or lava.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 2, aspectH: 3),
        .init(id: "rcp.myth.gilded-void-crowned-figure", studio: "myth", title: "The Gilded Void", subjectExample: "a lone hooded figure shot from the chest up against a smooth cool grey-teal void, the deep black hood swallowing the whole face into flat featureless shadow with no features rendered, a slender golden spiked crown resting on top of the head above the hood as a separate metal object, both black-gloved hands laid flat one over the other low at the chest, a single thin gold chain draped across the wet-dark robe", chipIDs: ["light.chiaroscuro", "color.coldsteel", "env.gradientvoid", "lens.tele135"], note: "🟢 The pitch-black hood is the whole idea and it also dodges Klein's face-mangling — there is no face to render, only intentional flat shadow; gloved hands laid flat one over the other give a single solved shape and the crown is stated as a separate resting metal object so it won't fuse into the fabric.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 2, aspectH: 3),
        .init(id: "rcp.cinemamood.crimson-samurai-flower-mound", studio: "cinemamood", title: "Crimson Vigil", subjectExample: "a lone samurai seen from directly behind, kneeling motionless on a small dark earthen mound blanketed in vivid crimson flowers, wearing black lacquered plate armor, his helmet topped by two tall smooth pale curved metal crest-blades rising in a wide V, hands hidden out of frame, a few small dark maple leaves drifting through the air, set against a flat saturated blood-red field with no horizon", chipIDs: ["frame.negspace", "color.singlehue", "style.painterlyconcept"], note: "🟢 The fully back-turned figure means no face to mangle, and the black armored silhouette reads cleanly against flat red negative space; naming the crest as two smooth pale metal blades keeps them from smearing into organic antlers.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 9, aspectH: 16),
        .init(id: "rcp.brand.gold-leaf-negative-profile", studio: "brand", title: "Gold Leaf Profile", subjectExample: "A thickly painted abstract canvas in glossy black and metallic gold, palette-knife impasto ridges sweeping across the frame like windblown strokes. A woman's clean profile reads as a flat solid-black silhouette gap where no paint covers it, luminous gold showing beyond the edge, no eyes or facial features rendered inside the black shape. Trailing paint strokes flow outward from the silhouette like blown hair; fine gold flecks scatter over the deep black field.", chipIDs: ["style.oilpaint", "light.chiaroscuro", "frame.negspace", "color.amberblack"], note: "🟡 The profile must stay a flat solid-black silhouette gap with zero features so Klein never models eyes, skin, or a 3D face; the impasto ridges and gold splatter carry all the luxe drama.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 9, aspectH: 16),
        .init(id: "rcp.nature.gilded-black-bison", studio: "nature", title: "Gilded Black Bison", subjectExample: "an extreme close-up of a black bison's face against pure darkness, the frame filled with wet near-black fur, a single amber-green eye sharp and awake with one clean catchlight, thin ragged flakes and torn ribbons of real gold leaf deliberately pressed and gilded into the fur across the brow and cheekbone beside that one eye, the muzzle and far side of the face dissolving smoothly into deep shadow", chipIDs: ["color.amberblack", "light.wildliferim", "env.darkseamless", "lens.tele135"], note: "🟢 One animal, one eye, and gold leaf gilded into fur — all real photographable materials, no hands, text, or face-in-chrome; naming the gold as deliberate gilding stops it reading as a wound and the single catchlight keeps one eye alive against the black.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 4),
        .init(id: "rcp.cinema.warrior-desert-duststorm-stand", studio: "cinema", title: "Against the Dust Wall", subjectExample: "A lone warrior in battered plate-and-leather armor and a plumed closed-visor helmet that fully hides the face, braced low in a fighting crouch on windswept desert sand, one gauntleted hand clenched in a raised fist and the other hand gripping a single tall spear shaft planted upright in the sand beside him, facing a towering backlit wall of golden dust surging up from the dunes ahead, drifting sand glowing around his silhouette.", chipIDs: ["style.gritwar", "color.furyamber", "light.dustplume", "lens.tele135"], note: "🟡 The monster is replaced by a real backlit dust storm so nothing gets literalized into an absurd creature; the closed visor hides the face and both hands get solved shapes (one clenched fist, one on a single straight spear shaft), with 19 steps as the one caution for the visible hands.", badge: .yellow, featured: true, tier: .klein9B, steps: 19, aspectW: 2, aspectH: 3),
        .init(id: "rcp.portrait.pixel-mapped-face", studio: "portrait", title: "Pixel-Mapped Face", subjectExample: "Head-and-shoulders portrait of a woman emerging from near-black darkness, a dense grid of multicolored LED pixel-dots projected across her face and dark high-neck top like light thrown from a screen, hair pulled back smooth, glossy lips and a calm gaze turned slightly off camera, no hands in frame; at the right edge a separate defocused wall of glowing colored pixel blocks melts into soft abstract bokeh with no readable pattern.", chipIDs: ["env.darkseamless", "color.technicolor", "lens.tele135", "env.bokehlights"], note: "🟡 Projected pixel light on skin is additive so Klein renders it cleanly; the one caution is patterned eyes-to-camera softening features, so the gaze turns slightly off camera, the LED wall stays pure bokeh to dodge pseudo-text, and 20 steps keep the face crisp.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 9, aspectH: 16),
        .init(id: "rcp.nature.golden-dust-plume-sunburst", studio: "nature", title: "Dust of Suns", subjectExample: "The dark crest of a tall sand dune cuts a steep diagonal ridge across the frame while a strong wind tears a towering plume of fine sand and dust off the crest, the low sun bursting just behind the ridge so every airborne grain glows brilliant gold against the shadowed dune and a deep near-black sky, sparkling amber and white specks scattering into the darkness, no people, no text", chipIDs: ["light.dustplume", "light.sunstar", "env.sanddunes", "color.crushedblacks"], note: "🟢 A real backlit sand plume delivers the glowing-gold-particulate-against-black look with no galaxy metaphor for Klein to literalize, and crushed blacks pin the deep sky instead of a Mad Max grade fighting it; no hands, faces, text, or handled objects anywhere.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 5, aspectH: 7),
        .init(id: "rcp.cinemamood.green-code-wall-lone-figure", studio: "cinemamood", title: "Wall of Code", subjectExample: "a single small person standing as a pure black silhouette at the base of an immense flat vertical wall rising far above them, the wall a separate surface behind the figure and not touching them, its whole face covered in dense cascading columns of glowing emerald-green numeric glyphs, every character unreadable and thrown softly out of focus, both hands hanging relaxed at the sides, the dark floor wet and mirroring faint green glints below", chipIDs: ["env.darkseamless", "color.singlehue", "frame.establishing", "env.wetfloor"], note: "🟢 The figure stays a pure black silhouette so no face can mangle and the wall is named a separate surface behind them, not held or fused; every glyph is unreadable out-of-focus digital rain, so Klein's garbled pseudo-text becomes the intended texture rather than a flaw.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 4),
        .init(id: "rcp.portrait.red-satin-corridor-glance", studio: "portrait", title: "Corridor Glance", subjectExample: "a young woman standing in a long narrow warm-lit hotel corridor at night, her body turned away from camera but her head glancing back over one shoulder with a soft closed-lip smile, wearing a short scarlet satin slip dress with thin straps, one hand resting flat on her hip and the other hanging relaxed at her side, a single warm ceiling lamp glowing far down the hall, plain doors and any numbers thrown softly out of focus", chipIDs: ["pose.overshoulder", "light.practical", "color.cinestill800t", "lens.film35"], note: "🟡 The over-the-shoulder glance keeps the face at a clean three-quarter angle and both hands sit in solved shapes (flat on hip, relaxed at side) so no hem-pinch mangles; run 20 steps because face and one hand are visible.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 4),
        .init(id: "rcp.portrait.helmet-visor-portrait", studio: "portrait", title: "Visor Light", subjectExample: "a young pilot's face framed chest-up inside a vintage flight helmet, its curved clear bubble visor lowered as a single separate glass pane a hand's width in front of her face, not touching her skin, the visor beaded with water droplets and faint scratches near its top edge, a bright specular sun-glare washing across the upper visor and forehead while her eyes and mouth stay in a clean lower pocket, warm low sun raking her left cheek, right side dropping into cool shadow, gaze steady off to one side, shoulders relaxed below frame", chipIDs: ["color.cinestill50d", "light.mccurry", "lens.tele135"], note: "🟡 A face behind curved reflective glass is Klein's rule-7 mangle case; I defended by pushing the glare, droplets and scratches to the UPPER visor and forehead so the eyes and mouth read clean, keeping the visor a separate un-touching pane and running 20 steps.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 4),
        .init(id: "rcp.cinemamood.hooded-crouch-foggy-rooftop", studio: "cinemamood", title: "Grey Vigil", subjectExample: "a lone figure crouched low on a bare concrete rooftop ledge, seen in three-quarter profile, a heavy hood pulled far forward so the face is entirely lost in deep black shadow; layered charcoal tactical gear with a backpack. One gloved hand rests flat on the knee; the other is wrapped around the single vertical grip of one separate matte-black rifle-shaped prop held diagonally across the chest, muzzle angled down, clearly apart from the gear. A pale foggy skyline dissolves softly behind.", chipIDs: ["color.coldsteel", "light.hazeback", "lens.tele135", "env.rooftopview"], note: "🟢 The forward hood swallows the face so Klein's worst failure is designed out, both hands get solved shapes (one flat on the knee, one around a single grip), and the skyline is thrown into fog so no tiny windows smear.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 2, aspectH: 3),
        .init(id: "rcp.cartoon3d.glossy-red-halo-android-profile", studio: "cartoon3d", title: "Halo Android", subjectExample: "a humanoid android shown from the chest up in sharp side profile, its head a smooth featureless white ceramic mask fused with exposed black gears, coiled cables and one glowing blue lens where an ear would sit, wearing a high-gloss cherry-red hooded vinyl raincoat with a plain black shoulder patch and one small blank yellow label, a bright glowing white ring floating behind the head against a flat aqua studio background", chipIDs: ["style.render3d", "light.octagloss", "frame.negspace"], note: "🟢 No human face and no hands: the head is a featureless ceramic-and-machine mask, so the glossy red vinyl renders cleanly with an octabox catchlight and there's nothing to mangle; the yellow label stays blank so Klein can't invent garbled text.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 2, aspectH: 3),
        .init(id: "rcp.cinemamood.hooded-figure-light-vortex", studio: "cinemamood", title: "Vortex of Light", subjectExample: "a lone figure in a long plain dark hooded robe, standing perfectly still with its back fully to the camera at the center of a pure black void, the face completely hidden in the deep shadow of the hood and the arms lost inside long draping sleeves. Ribbons of red, green, blue and white long-exposure light trails sweep in a smooth S-curve around the feet and spiral up behind the figure.", chipIDs: ["env.lightstreaks", "lens.lightstreaks", "style.silhouettefirst", "color.crushedblacks"], note: "🟢 Back turned and face buried in the hood leaves nothing for Klein to mangle, and the arms hidden in draping sleeves remove hands entirely; the abstract light trails are a real long-exposure phenomenon, so their smear reads as intentional.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 4, aspectH: 5),
        .init(id: "rcp.cinemamood.lone-figure-golden-startrail-sweep", studio: "cinemamood", title: "The Golden Vortex", subjectExample: "a single tiny person in full silhouette from behind, standing dead center far away on a vast mirror-smooth wet salt flat, arms hanging straight and relaxed at their sides, facing one blinding low golden light on the horizon; above them huge sweeping curved long-exposure star-trail light streaks and countless glowing star points arc across the black sky, the whole warm blaze mirrored crisply in the wet flat below", chipIDs: ["lens.lightstreaks", "env.wetslate", "light.hazeback", "color.amberblack"], note: "🟢 The figure stays a distant faceless back-lit silhouette with arms straight at its sides, so there is no face or hands to mangle; the vortex is grounded as real long-exposure star-trail streaks over a wet flat, a photographable phenomenon rather than an impossible tunnel.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 2, aspectH: 3),
        .init(id: "rcp.myth.desert-galleon-dune-wake", studio: "myth", title: "Ship of the Dunes", subjectExample: "A weathered wooden sailing ship crossing vast rippled sand dunes at golden hour, seen from a low oblique aerial angle. Its tattered off-white canvas sails are plain and weather-stained with no emblem or writing. Dry pale sand curls and sprays off the hull like a bow-wave, backlit by a low hazy sun into a glowing rim. Faint footprints trail across the empty foreground sand. No people aboard, no crew, no flags.", chipIDs: ["angle.oblique45", "light.dustplume", "light.harmattan", "env.sanddunes"], note: "🟢 The one surreal beat — pale sand spraying off the hull like surf — is just backlit dry dust, which Klein renders literally; the sails are kept plain and unmarked so no garbled crest or map-text appears, and with no crew there are no tiny faces or hands to smear.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 2, aspectH: 3),
        .init(id: "rcp.cities.night-tube-flash-bomber", studio: "cities", title: "Last Train Home", subjectExample: "a young blonde woman sitting alone on a patterned fabric seat inside a night subway car, wearing an oversized olive bomber jacket with a bright orange lining over a plain white tank top, a pink spiked choker worn as a separate collar at her throat apart from the jacket, both hands resting loosely in her lap, gazing off to one side, the dark train window behind her a blank reflective panel of blown-out white flare with no legible signage", chipIDs: ["env.subwayplatform", "lens.phonesnap", "light.hardsingle", "color.cinestill800t"], note: "🟡 A single hard on-camera flash blows out fine facial detail and turns the window into an abstract white glare, so Klein never renders a face through reflective glass; both hands resting in the lap replaces the reference's risky finger-to-lips pose.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 4),
        .init(id: "rcp.nature.heads-golden-sea-sunset", studio: "nature", title: "Heads on the Golden Sea", subjectExample: "Open calm sea at sunset, the low sun a soft dimmed disc just above the far horizon under a thin cloud band, laying one long shimmering golden reflection straight down the centre toward the camera. Five swimmers far out and well separated, each submerged to the neck so only a small dark rounded head breaks the rippled water as a distant backlit silhouette. No faces, no limbs, no hands visible. Warm peach sky, gentle wavelet in the near foreground.", chipIDs: ["light.harmattan", "light.hazeback", "color.fadedpostcard", "lens.film35"], note: "🟢 Safe: the swimmers are far, backlit and submerged to the neck so their tiny heads read as intentional distant silhouettes — no faces, limbs or hands for Klein to garble — and the golden sun-path is a real, easily-rendered phenomenon.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 3, aspectH: 4),
        .init(id: "rcp.gameconcept.frozen-sanctum-cupped-glow", studio: "gameconcept", title: "The Frozen Sanctum", subjectExample: "A single small pale figure crouched low on a bare rock island in a still black pool inside a vast ice cavern, seen from far off in near-profile, the bald head bowed so the face is lost in shadow, both hands cupped together around one small round glowing stone held at chest height. A single cold shaft of light falls from a break in the ceiling through misty air, huge icicles hanging above, faint concentric ripples on the water.", chipIDs: ["light.godrays", "style.painterlyconcept", "color.coldsteel", "style.silhouettefirst"], note: "🟡 The figure stays tiny, distant and bowed so the face reads as a shadowed silhouette, never smearing; both hands cup one simple round stone giving the hands a single solved shape, and the glow is a real small object, not a spirit-light. Push to 20 steps for the cupped hands.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 10, aspectH: 16),
        .init(id: "rcp.myth.hooded-rider-misty-ravine", studio: "myth", title: "The Silent Ridge", subjectExample: "a single tiny hooded rider seated on a dark horse standing still on a rocky ridge, seen small and distant so the shadowed face never resolves, one hand resting flat on the saddle, thin reins hanging loose; a tall arch of bare gnarled leafless branches frames a bright misty white ravine beyond, rust-red moss on dark wet boulders below", chipIDs: ["env.perspective", "light.hazeback", "color.coldsteel"], note: "🟢 The rider is a tiny distant silhouette with the face lost in the hood and one hand flat on the saddle, so nothing forces Klein to resolve a face or tangle reins; the bright misty backlight and bare branch arch carry the whole mood.", badge: .green, featured: true, tier: .klein9B, steps: 18, aspectW: 3, aspectH: 4),
        .init(id: "rcp.travel.tricolour-tall-ship-harbor", studio: "travel", title: "Tricolour Harbor", subjectExample: "A towering wooden multi-masted sailing frigate with tall rigging and furled canvas sails glides into a busy 19th-century European stone harbor at golden hour, one large plain vertical blue-white-red tricolour banner hanging slack from its rigging as a simple color-field with no emblem, more tall ships fading into haze behind, the far quay and small boats crowded with tiny distant people reading only as dark backlit silhouettes, grand old stone townhouses lining the water under big cumulus clouds.", chipIDs: ["env.perspective", "light.hazeback", "color.amberblack", "frame.establishing"], note: "🟡 The crowd is the only fragile element, so it is pushed far and thrown into backlit haze silhouette where the inevitable face-smear reads as distance, not error; the flag is locked as a plain blue-white-red color-field with no heraldry or text.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 5, aspectH: 7),
        .init(id: "rcp.portrait.white-fur-hood-portrait", studio: "portrait", title: "Fur-Framed Warmth", subjectExample: "A woman's calm face framed head-on, haloed by the enormous plush white fox-fur hood of a coat she wears, only her face visible in the soft fur opening, both hands out of frame below. Cream fur glows against warm deep skin; long lashes, glossy lips. A honey-toned pine cabin wall sits softly blurred behind her, gentle window daylight wrapping her face.", chipIDs: ["light.butterfly", "color.cinestill50d", "env.cabin"], note: "🟢 A single centered face ringed by fur, hands out of frame and no phone, screen, or reflection anywhere, so Klein's only job is skin and fur, which it renders superbly.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 9, aspectH: 16),
        .init(id: "rcp.portrait.chin-on-hands-floral-bed", studio: "portrait", title: "Faded Afternoon", subjectExample: "A young woman lies prone on a floral-patterned bedspread, seen from a high angle looking down, her cheeks resting on the backs of both hands with fingers tucked together into one calm rounded shape, elbows planted, gazing softly up toward the camera. A striped pillow sits behind her. On the quilt in front lie a few old photographs, all face-down so only their blank pale backs show, thrown gently out of focus. Warm faded afternoon window light, fine film grain.", chipIDs: ["angle.birdseye", "color.faded", "lens.film35", "light.singlesoft"], note: "🟡 Cheeks-on-both-hands collapses to one rounded shape and the props are face-down blank backs so Klein never draws tiny faces or text — hold 20 steps for the hands and the one prominent face.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 2, aspectH: 3),
        .init(id: "rcp.portrait.living-face-marble-busts", studio: "portrait", title: "The Living Face", subjectExample: "a young woman with dark hair pulled into a neat topknot and a plain black top, framed from the shoulders up at the center, facing the camera with a calm neutral expression, her warm living skin the one real face; all around her, packed close on every side, stand dozens of separate white marble classical busts with smooth blank carved eyes and sculpted wavy hair, each a distinct stone head, no hands in frame", chipIDs: ["light.refeven", "lens.tele135", "color.coldsteel", "env.darkseamless"], note: "🟢 The busts' blank carved eyes make the wall of faces read as intentional stone, sidestepping the crowd-of-humans smear; only one real face must render, kept sharp at 20 steps with no hands in frame.", badge: .green, featured: true, tier: .klein9B, steps: 20, aspectW: 2, aspectH: 3),
        .init(id: "rcp.cities.worms-eye-sidewalk-lean", studio: "cities", title: "Tall Order", subjectExample: "Extreme worm's-eye view up a young woman in a plain grey tee and rolled blue denim shorts, leaning her back and shoulders against a beige plaster building wall on a city sidewalk. One hand rests flat against the wall by her hip, the other hangs straight at her side with fingers together. Behind her a tree-lined street with parked cars recedes; a few distant pedestrians and street signs stay soft and blurred under a flat overcast white sky.", chipIDs: ["angle.wormseye", "lens.35mm", "color.faded", "light.bounce"], note: "🟡 The steep worm's-eye angle sells the forced-perspective height; both hands get solved shapes (flat on wall, straight at side) and all signage plus plates are thrown to blur so no garbled text appears.", badge: .yellow, featured: false, tier: .klein9B, steps: 20, aspectW: 9, aspectH: 16),
        .init(id: "rcp.gameconcept.neon-grid-ringed-planet", studio: "gameconcept", title: "Outrun Horizon", subjectExample: "A single smooth stone pyramid standing alone at the center of a vast dark desert plain, a glowing magenta neon wireframe grid laid flat across the sand and receding straight to the horizon behind it. Low on the horizon a huge ringed planet-disc glows amber-gold across its top and hot pink below, one flat pale ring crossing it. A lone palm silhouette and scattered dark rocks flank the grid, black star-filled sky above.", chipIDs: ["style.vhs80s", "color.ovaneon80s", "env.starrynight", "frame.establishing"], note: "🟢 Pure people-free landscape of simple readable solids — a smooth pyramid, a flat neon grid receding to the horizon, and a single glowing ringed disc — none of Klein's face/hand/text failure modes apply.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 2, aspectH: 3),
        .init(id: "rcp.macro.gilded-marble-tears", studio: "macro", title: "Gilded Marble Tears", subjectExample: "extreme macro of a carved white-and-black veined marble sculpture of a calm face, filling the frame from brow to nose; the eye socket holds a separate polished amber-and-gold cabochon inlay glowing warm, not a living eye; glossy black-and-gold liquid is poured over the stone as its own layer and runs down in thin wet rivulets, resting on the marble surface rather than fused into it; hard low raking light gleaming on every wet thread and the pitted veined stone", chipIDs: ["color.amberblack", "lens.stacked", "light.grazetexture"], note: "🟡 Making it a marble sculpture with an inlaid amber-gold cabochon (not a living eye) dodges the eye-behind-wet-liquid mangle, and stating the black-gold as a separate poured liquid resting on the stone stops Klein fusing it into skin.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 3, aspectH: 4),
        .init(id: "rcp.gameconcept.green-glow-biomech-creature", studio: "gameconcept", title: "Toxic Bloom", subjectExample: "A full-length gaunt biomechanical creature standing alone on a dark factory floor, its wet glossy-black exoskeleton stretched over a believable exposed ribcage and long thin limbs, plain rusted metal bands clamped on its forearms. Both long-clawed hands hang relaxed and open at its sides. Toxic-green light glows from deep inside its chest and its featureless eye sockets. Thick green-tinted haze drifts around its legs; dim ceiling lights and blurred green tanks sit far behind.", chipIDs: ["style.creatureanatomy", "env.factoryfloor", "light.hazeback", "color.singlehue"], note: "🟡 Hands hang relaxed and open at the sides and the head is a featureless nonhuman creature head, so the two long-clawed hands and the glossy sheen have no human-face fidelity to wreck; the green reads as real backlit haze and internal glow, not a metaphor, and the background tanks stay blurred so no garbled labels appear.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 2, aspectH: 3),
        .init(id: "rcp.cinema.explorers-map-tallship-pov", studio: "cinema", title: "The Explorer's Map", subjectExample: "First-person point of view over the deck of a wooden tall ship in rough open sea, two weathered sun-tanned hands held forward, each palm flat and thumb-pressed against one edge of a single aged parchment sheet holding it open, the parchment a separate loose object apart from the bare forearms and not fused to any sleeve, its faint brown map linework thrown soft and out of focus, tangled rigging ropes and canvas along the left, churning teal ocean swells and distant jagged rock peaks under a bright hazy sky ahead", chipIDs: ["color.tealorange", "lens.35mmcandid", "light.hazeback"], note: "🟡 Both hands are prominent so run 20 steps with each hand solved as a flat thumb-press on one edge of the single sheet; the parchment is named a separate loose object apart from the bare forearms so it can't fuse into a sleeve, and its map linework stays out of focus so Klein can't invent legible text.", badge: .yellow, featured: true, tier: .klein9B, steps: 20, aspectW: 5, aspectH: 7),
        .init(id: "rcp.interiors.spiral-stair-piano-well", studio: "interiors", title: "The Spiral Well", subjectExample: "looking straight down the open eye of a modern spiral staircase, pale cream stone treads curving tightly around a smooth teal-blue metal balustrade capped with a dark wood handrail, and far below on a separate dark circular floor a single grand piano rests centered and tiny with distance, its lid a clean rounded silhouette, cool daylight raking down the well", chipIDs: ["angle.birdseye", "frame.frameinframe", "color.tealorange", "light.toplight"], note: "🟢 Pure architecture and one rigid object seen from far above, no people, hands, faces or text to mangle; the piano stays a tiny clean silhouette on its own floor and teal-orange nails the teal-balustrade-versus-warm-cream-stone split.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 16, aspectH: 9),
        // === IDEA batch 2 (2026-07-05, flux2/ideogram refs, concept-grounded) ===
        .init(id: "rcp.food.avocado-poached-flatlay", studio: "food", title: "Green Toast, Two Eggs", subjectExample: "an overhead flatlay straight down on dark charcoal linen: a white speckled ceramic plate holding a thick slice of toasted dark sourdough spread with mashed avocado, topped with two soft poached eggs, one broken so the yolk runs gold, scattered chilli flakes and thyme leaves, and beside the plate a matching speckled mug of latte with a soft leaf-shaped foam rosette, loose thyme sprigs strewn across the cloth", chipIDs: ["angle.birdseye", "light.singlesoft", "color.softmatte"], note: "🟢 Food flatlay is Klein's strong suit — the running yolk and latte foam rosette are abstract organic shapes, not text, so nothing garbles; the dark linen keeps it moody rather than catalogue-clean.", badge: .green, featured: true, tier: .klein9B, steps: 16, aspectW: 1, aspectH: 1),
        .init(id: "rcp.portrait.amber-kimono-temple", studio: "portrait", title: "Amber Kimono", subjectExample: "an ornate oil painting of a woman seen in profile from the shoulders up, glancing quietly to one side, wearing a richly patterned red-and-gold floral kimono, her black hair swept into a low knot dressed with gilded ornaments and deep-red blossoms and a single red drop earring, a lantern-lit wooden pagoda and warm stone stairway glowing behind her among autumn foliage, thick palette-knife impasto", chipIDs: ["style.oilpaint", "color.amberblack", "light.firelight"], note: "🟡 The ornate hair ornaments and kimono pattern are forgiving under heavy impasto — the palette-knife texture hides fine-detail wobble, and the chest-up profile keeps hands out of frame. 18 steps for the face.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 5, aspectH: 7),
        .init(id: "rcp.cinemamood.astronomer-nebula-study", studio: "cinemamood", title: "The Star-Chart Room", subjectExample: "a symmetrical wide view of an old astronomer in a dark coat hunched over unrolled star-charts at a cluttered wooden desk in a shadowy panelled study, a single oil lamp pooling warm light on his work, brass armillary spheres and globes flanking him and tall bookshelves behind, two huge round brass-rimmed porthole windows to either side, and above the desk a vast purple-and-teal nebula filling the space with a faint glowing web of constellation lines and scattered stars", chipIDs: ["angle.onepoint", "light.practical", "color.crushedblacks"], note: "🟡 The seated figure stays small with his hands resting on the desk near the lamp, and the constellation is an abstract web of lines and points with no labels — so no mangled close-up hands and no garbled text. 18 steps.", badge: .yellow, featured: true, tier: .klein9B, steps: 18, aspectW: 1, aspectH: 1),
    ]

    static let redPanel: [RedPanelRow] = [
        .init(trap: "Legible text in the image", who: "Poster / flyer / menu designers, marketers, thumbnail makers, social-media creators", fails: "Posters, flyers, menus, ad copy, captions, subtitles, video-thumbnail text and any words longer than a word or two come out misspelled, garbled or invented — and the 4-step model is worse at it than slower models. Reserved 'empty space for your headline' is a bias, not a guarantee.", reframe: "Generate the artwork, backdrop or scene here, then drop the real text on top in Canva, Figma, Keynote, Photoshop or Pages — where it stays sharp and you can edit it."),
        .init(trap: "App icons, UI mockups, vector & transparent assets", who: "App / web designers, brand & product teams, anyone needing an SVG or a transparent PNG", fails: "No real vector (SVG) output, no built-in transparency or cut-out, no pixel-exact buttons / toolbars / screens. You get a flat raster painting of an interface, not a usable icon or editable layout — sizes and pixels won't line up.", reframe: "Use it for moodboards, hero imagery and 'what could this look like' concepts, then build the actual icon or UI in Figma / Sketch / Illustrator. For a cut-out, remove the background afterward in a dedicated tool."),
        .init(trap: "Real 3D files, CAD & dimensioned drawings", who: "Product / industrial designers, architects, engineers, 3D artists, makers", fails: "It only paints a 2D picture that looks 3D. No .obj / .stl / STEP file, no CAD geometry, no measured floor plans, no dimensioned or to-scale technical drawings — nothing you can print, mill or rotate. There's also no turnaround: each angle is a different, inconsistent object.", reframe: "Great for early concept art and 'mood' renders to show a direction. For anything buildable, model it in Blender / Fusion 360 / SketchUp / a CAD tool, where measurements are real."),
        .init(trap: "Charts, maps, gauges, readable numbers & code", who: "Analysts, data / BI teams, finance, dashboard & infographic designers, developers", fails: "Graphs, diagrams, maps, dashboards, dials, tables, prices, phone numbers, code on a screen — the numbers and labels are fake and the geometry doesn't add up. It paints something chart-shaped, not your data.", reframe: "Use it for the decorative frame or background only. Make the actual chart in Excel / Sheets / a BI tool, the map in a maps service, and screenshot real code — then composite if you want the styled look."),
        .init(trap: "Exact brand logos & trademarks", who: "Brand designers, agencies, anyone placing a company logo", fails: "It can't reproduce a real logo accurately — it hallucinates a junk pseudo-logo, even on a surface you asked to keep blank (a 'plain' bottle, sign or jersey). Wordmarks come out as garbled lettering.", reframe: "Generate the product, packaging or scene with a clean, empty surface, then place the official logo file yourself in an editor — that's also the only way to stay on-brand and avoid trademark trouble."),
        .init(trap: "The same character, product or room across images", who: "Comic / storyboard artists, brand & product photographers, game & film pre-viz", fails: "Every render is independent — no consistent character, mascot, product or set across a series, and no 360° turnaround. Faces are good but not flawless, and crowds and hands degrade on 4 steps (it leans toward a single, small subject).", reframe: "Use it for one-off hero shots and concept frames. For a consistent cast or product line, train or use a LoRA, lean on flattering light and lens for faces, and keep the scene to one or two subjects."),
        .init(trap: "Medical & diagnostic imagery", who: "Clinicians, medical educators, health publishers, patients", fails: "A realistic-looking X-ray, scan, skin photo, lab result or anatomy figure is invented — confidently wrong details that could be mistaken for a real diagnosis. We ship no medical preset because a believable fake here is dangerous, not helpful.", reframe: "For teaching or illustration, use licensed medical atlases and real, consented clinical images. Never present a generated image as a real scan or as medical evidence."),
        .init(trap: "News, events & 'real' photos of real people", who: "Journalists, editors, fact-checkers, PR, social-media managers", fails: "It can paint a photoreal 'news photo' of an event that never happened or a public figure doing something they didn't — and it looks real enough to deceive. There's no provenance and no studio preset for this, on purpose.", reframe: "Use real, sourced photography for anything presented as news or as a real event. If you make an illustration, label it clearly as an illustration / AI-generated so no one mistakes it for a record of fact."),
        .init(trap: "Police, forensic & surveillance use", who: "Law enforcement, investigators, legal, security teams", fails: "No reliable face match, no 'enhance' of a blurry photo into a real identity, no evidence-grade reconstruction. It invents plausible-looking detail that isn't in the source — which can implicate the wrong person. We provide no studio for this.", reframe: "Treat generated images as never admissible and never identifying. Use validated forensic tools and chain-of-custody evidence for anything that affects a real person's case."),
        .init(trap: "Anything you need exact and repeatable", who: "Print production, spec / handoff, QA, regulated industries", fails: "It won't hit an exact color value, exact dimensions, exact placement, a specific font, or the same result on demand from a vague prompt. Tiny details drift between renders.", reframe: "Let it generate the look and the variations, then lock the exact specs (color, size, type, layout) in a real design / print tool. Save the seed and recipe if you want to get close to a render again."),
    ]
}

enum StudioPriority: String, Sendable { case top, high, med }

struct LibraryStudio: Identifiable, Hashable, Sendable {
    let id: String
    let title: String
    let badge: PresetBadge
    let icon: String
    let priority: StudioPriority
}

struct SceneRecipe: Identifiable, Hashable, Sendable, Codable {
    let id: String
    let studio: String
    let title: String
    let subjectExample: String
    let chipIDs: [String]
    let note: String
    let badge: PresetBadge
    let featured: Bool
    // Pinned generation settings so a recipe reproduces its bundled preview EXACTLY: load it →
    // Generate → the same image; swap the subject → the same quality with your own idea. All
    // optional — nil means "use the form's current dial", so pre-settings recipes are unchanged.
    let tier: ModelTier?
    let steps: Int?
    let quality: QualityPreset?
    let aspectW: Int?
    let aspectH: Int?
    let seed: UInt64?

    init(id: String, studio: String, title: String, subjectExample: String,
         chipIDs: [String], note: String, badge: PresetBadge, featured: Bool,
         tier: ModelTier? = nil, steps: Int? = nil, quality: QualityPreset? = nil,
         aspectW: Int? = nil, aspectH: Int? = nil, seed: UInt64? = nil) {
        self.id = id
        self.studio = studio
        self.title = title
        self.subjectExample = subjectExample
        self.chipIDs = chipIDs
        self.note = note
        self.badge = badge
        self.featured = featured
        self.tier = tier
        self.steps = steps
        self.quality = quality
        self.aspectW = aspectW
        self.aspectH = aspectH
        self.seed = seed
    }
}

struct RedPanelRow: Identifiable, Hashable, Sendable {
    var id: String { trap }
    let trap: String
    let who: String
    let fails: String
    let reframe: String
}
